// Mock Initial Data
const INITIAL_VENDORS: Vendor[] = [
  { id: 'v1', name: '兴隆蔬菜批发', contact: '张老板', phone: '13800138000', address: '新发地市场A区', categories: [Category.VEGETABLE, Category.FRUIT], paymentMethod: '周结' },
  { id: 'v2', name: '诚顺肉品供应', contact: '王经理', phone: '13900139000', address: '新发地市场B区', categories: [Category.MEAT], paymentMethod: '日结' },
];

const INITIAL_INVENTORY: InventoryItem[] = [
  { id: 'i1', name: '大白菜', category: Category.VEGETABLE, unit: 'kg', price: 2.5, currentStock: 45, minStock: 50, shelfLifeDays: 5, lastRestockDate: '2023-11-20' },
  { id: 'i2', name: '猪里脊', category: Category.MEAT, unit: 'kg', price: 32, currentStock: 12, minStock: 10, shelfLifeDays: 3, lastRestockDate: '2023-11-22' },
  { id: 'i3', name: '青岛啤酒', category: Category.BEVERAGE, unit: '箱', price: 48, currentStock: 5, minStock: 10, shelfLifeDays: 365, lastRestockDate: '2023-10-15' },
];

export default function App() {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [vendors, setVendors] = useState<Vendor[]>(INITIAL_VENDORS);
  const [inventory, setInventory] = useState<InventoryItem[]>(INITIAL_INVENTORY);
  const [deliveryNotes, setDeliveryNotes] = useState<DeliveryNote[]>([]);
  const [notifications, setNotifications] = useState<string[]>([]);

  // Simple alert simulation
  useEffect(() => {
    const lowStock = inventory.filter(i => i.currentStock < i.minStock);
    if (lowStock.length > 0) {
      setNotifications(prev => [...new Set([...prev, `有 ${lowStock.length} 个项目库存低于预警值`)]);
    }
  }, [inventory]);

  const handleUpdateStock = (itemId: string, amount: number) => {
    setInventory(prev => prev.map(item => 
      item.id === itemId ? { ...item, currentStock: Math.max(0, item.currentStock + amount) } : item
    ));
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard inventory={inventory} vendors={vendors} deliveryNotes={deliveryNotes} />;
      case 'inventory':
        return <InventoryList inventory={inventory} onUpdateStock={handleUpdateStock} />;
      case 'delivery':
        return (
          <InventoryEntry 
            vendors={vendors} 
            inventory={inventory}
            onComplete={(note) => {
              setDeliveryNotes(prev => [note, ...prev]);
              // Update inventory based on entry
              const updatedInventory = [...inventory];
              note.items.forEach(item => {
                const existing = updatedInventory.find(i => i.name === item.name);
                if (existing) {
                  existing.currentStock += item.quantity;
                  existing.lastRestockDate = note.date;
                } else {
                  updatedInventory.push({
                    id: `i-${Date.now()}-${Math.random()}`,
                    name: item.name,
                    category: item.category,
                    unit: item.unit,
                    price: item.price,
                    currentStock: item.quantity,
                    minStock: 10,
                    shelfLifeDays: 3,
                    lastRestockDate: note.date
                  });
                }
              });
              setInventory(updatedInventory);
              setActiveTab('dashboard');
            }}
          />
        );
      case 'vendors':
        return <VendorManagement vendors={vendors} onAddVendor={(v) => setVendors([...vendors, v])} />;
      case 'analytics':
        return <Analytics inventory={inventory} deliveryNotes={deliveryNotes} />;
      case 'settings':
        return <SettingsView />;
      default:
        return <Dashboard inventory={inventory} vendors={vendors} deliveryNotes={deliveryNotes} />;
    }
  };

  return (
    <div className="flex h-screen overflow-hidden bg-gray-50 font-sans">
      {/* Sidebar */}
      <aside className={`${isSidebarOpen ? 'w-64' : 'w-20'} bg-white border-r border-gray-200 transition-all duration-300 flex flex-col z-30`}>
        <div className="p-6 flex items-center gap-3">
          <div className="w-8 h-8 bg-emerald-600 rounded-lg flex items-center justify-center text-white font-bold">餐</div>
          {isSidebarOpen && <span className="font-bold text-xl tracking-tight text-emerald-800">餐管家</span>}
        </div>

        <nav className="flex-1 mt-4 px-3 space-y-1">
          {NAV_ITEMS.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-3 px-3 py-3 rounded-lg transition-colors ${
                activeTab === item.id 
                  ? 'bg-emerald-50 text-emerald-700 font-medium' 
                  : 'text-slate-600 hover:bg-gray-100'
              }`}
            >
              <span className={activeTab === item.id ? 'text-emerald-600' : 'text-slate-400'}>
                {item.icon}
              </span>
              {isSidebarOpen && <span>{item.label}</span>}
              {activeTab === item.id && isSidebarOpen && <ChevronRight size={16} className="ml-auto" />}
            </button>
          ))}
        </nav>

        <div className="p-4 border-t border-gray-100">
          <button 
            onClick={() => setIsSidebarOpen(!isSidebarOpen)}
            className="w-full flex items-center gap-3 px-3 py-2 text-slate-500 hover:bg-gray-100 rounded-lg"
          >
