import React, { useState, useRef, useCallback } from 'react';
import { Camera, FileUp, Plus, Trash2, CheckCircle, Loader2, Image as ImageIcon } from 'lucide-react';
import { scanDeliveryNote } from '../services/gemini';
import { Vendor, InventoryItem, DeliveryNote, DeliveryItem, Category } from '../types';
import { CATEGORIES, UNITS } from '../constants';

interface InventoryEntryProps {
  vendors: Vendor[];
  inventory: InventoryItem[];
  onComplete: (note: DeliveryNote) => void;
}

export default function InventoryEntry({ vendors, inventory, onComplete }: InventoryEntryProps) {
  const [entryMode, setEntryMode] = useState<'manual' | 'ai'>('ai');
  const [isLoading, setIsLoading] = useState(false);
  const [vendorId, setVendorId] = useState('');
  const [items, setItems] = useState<DeliveryItem[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsLoading(true);
    try {
      const reader = new FileReader();
      reader.onload = async () => {
        const base64 = (reader.result as string).split(',')[1];
        const result = await scanDeliveryNote(base64);

        // Match vendor
        const foundVendor = vendors.find(v => v.name.includes(result.vendorName) || result.vendorName.includes(v.name));
        if (foundVendor) setVendorId(foundVendor.id);

        setItems(result.items.map((it: any) => ({
          name: it.name,
          quantity: it.quantity,
          unit: it.unit,
          category: it.category as Category,
          price: it.price || 0
        })));
        setEntryMode('manual'); // Transition to manual to allow review
      };
      reader.readAsDataURL(file);
    } catch (error) {
      console.error(error);
      alert("识别失败，请检查网络或图片质量。");
    } finally {
      setIsLoading(false);
    }
  };

  const addItem = () => {
    setItems([...items, { name: '', quantity: 1, unit: 'kg', category: Category.OTHER, price: 0 }]);
  };

  const removeItem = (idx: number) => {
    setItems(items.filter((_, i) => i !== idx));
  };

  const updateItem = (idx: number, updates: Partial<DeliveryItem>) => {
    const newItems = [...items];
    newItems[idx] = { ...newItems[idx], ...updates };
    setItems(newItems);
  };

  const handleSave = () => {
    if (!vendorId || items.length === 0) {
      alert("请填写供应商信息并至少添加一个菜品。");
      return;
    }
    const vendor = vendors.find(v => v.id === vendorId);
    const note: DeliveryNote = {
      id: `dn-${Date.now()}`,
      vendorId,
      vendorName: vendor?.name || '未知',
      date: new Date().toISOString().split('T')[0],
      items,
      status: 'completed'
    };
    onComplete(note);
  };

  return (
    <div className="max-w-4xl mx-auto animate-in slide-in-from-bottom-4 duration-500">
      <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-gray-100">
        <div className="p-8 border-b border-gray-100 bg-gray-50/50">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-2xl font-bold text-slate-800">入库录入</h2>
            <div className="flex bg-gray-200 p-1 rounded-xl">
              <button 
                onClick={() => setEntryMode('ai')}
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${entryMode === 'ai' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
              >
                智能拍照
              </button>
              <button 
                onClick={() => setEntryMode('manual')}
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${entryMode === 'manual' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
              >
                手动精准录入
              </button>
            </div>
          </div>

          {entryMode === 'ai' && (
            <div className="flex flex-col items-center justify-center p-12 border-2 border-dashed border-emerald-200 rounded-2xl bg-emerald-50/30">
              {isLoading ? (
                <div className="text-center space-y-4">
                  <Loader2 className="animate-spin text-emerald-600 mx-auto" size={48} />
                  <p className="text-emerald-700 font-medium">正在 AI 识别送货单信息，请稍候...</p>
                </div>
              ) : (
                <div className="text-center space-y-6">
                  <div className="p-4 bg-emerald-100 rounded-full text-emerald-600 inline-block">
                    <Camera size={48} />
                  </div>
                  <div>
                    <h3 className="text-xl font-bold text-slate-800">拍照或上传送货单</h3>
                    <p className="text-slate-500 mt-2 max-w-xs mx-auto">系统将自动提取供应商、商品名、数量、价格及品类。</p>
                  </div>
                  <div className="flex gap-4 justify-center">
                    <button 
                      onClick={() => fileInputRef.current?.click()}
                      className="px-6 py-3 bg-emerald-600 text-white rounded-xl font-bold shadow-lg hover:bg-emerald-700 transition-all flex items-center gap-2"
                    >
                      <FileUp size={20} /> 选择图片
                    </button>
                  </div>
                  <input 
                    type="file" 
                    className="hidden" 
                    ref={fileInputRef} 
                    accept="image/*" 
                    onChange={handleFileUpload} 
                  />
                </div>
              )}
            </div>
          )}

          {entryMode === 'manual' && (
            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase">供应商选择</label>
                  <select 
                    value={vendorId}
                    onChange={(e) => setVendorId(e.target.value)}
                    className="w-full px-4 py-2 bg-white border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500"
                  >
                    <option value="">请选择供应商</option>
                    {vendors.map(v => <option key={v.id} value={v.id}>{v.name}</option>)}
                  </select>
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase">录入日期</label>
                  <input type="date" defaultValue={new Date().toISOString().split('T')[0]} className="w-full px-4 py-2 bg-white border border-gray-300 rounded-lg" />
                </div>
              </div>

              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <label className="text-xs font-bold text-slate-500 uppercase">清单详情 ({items.length})</label>
                  <button onClick={addItem} className="text-emerald-600 flex items-center gap-1 text-sm font-bold hover:underline">
                    <Plus size={16} /> 添加项目
                  </button>
                </div>

                <div className="space-y-3">
                  {items.map((item, idx) => (
                    <div key={idx} className="flex flex-wrap md:flex-nowrap gap-3 items-end p-4 bg-gray-50 rounded-xl border border-gray-100 group">
                      <div className="flex-1 min-w-[120px]">
                        <label className="block text-[10px] text-slate-400 mb-1">食材名称</label>
                        <input 
                          type="text" 
                          placeholder="例如：西红柿"
                          value={item.name}
                          onChange={(e) => updateItem(idx, { name: e.target.value })}
                          className="w-full px-3 py-1.5 border border-gray-200 rounded focus:ring-1 focus:ring-emerald-500 text-sm"
                        />
                      </div>
                      <div className="w-20">
                        <label className="block text-[10px] text-slate-400 mb-1">数量</label>
                        <input 
                          type="number" 
                          value={item.quantity}
                          onChange={(e) => updateItem(idx, { quantity: parseFloat(e.target.value) })}
                          className="w-full px-3 py-1.5 border border-gray-200 rounded focus:ring-1 focus:ring-emerald-500 text-sm"
                        />
                      </div>
                      <div className="w-20">
                        <label className="block text-[10px] text-slate-400 mb-1">单位</label>
                        <select 
                          value={item.unit}
                          onChange={(e) => updateItem(idx, { unit: e.target.value })}
                          className="w-full px-3 py-1.5 border border-gray-200 rounded focus:ring-1 focus:ring-emerald-500 text-sm"
                        >
                          {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                        </select>
                      </div>
                      <div className="w-32">
                        <label className="block text-[10px] text-slate-400 mb-1">品类</label>
                        <select 
                          value={item.category}
                          onChange={(e) => updateItem(idx, { category: e.target.value as Category })}
                          className="w-full px-3 py-1.5 border border-gray-200 rounded focus:ring-1 focus:ring-emerald-500 text-sm"
                        >
                          {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                      </div>
                      <div className="w-24">
                        <label className="block text-[10px] text-slate-400 mb-1">单价 (元)</label>
                        <input 
                          type="number" 
                          value={item.price}
                          onChange={(e) => updateItem(idx, { price: parseFloat(e.target.value) })}
                          className="w-full px-3 py-1.5 border border-gray-200 rounded focus:ring-1 focus:ring-emerald-500 text-sm"
                        />
                      </div>
                      <button onClick={() => removeItem(idx)} className="p-2 text-slate-400 hover:text-red-500 transition-colors">
                        <Trash2 size={18} />
                      </button>
                    </div>
                  ))}
                  {items.length === 0 && (
                    <div className="text-center py-12 text-slate-400 bg-gray-50 rounded-xl border border-dashed border-gray-200">
                      尚未添加任何项目，请点击上方“添加项目”或通过AI拍照导入。
                    </div>
                  )}
                </div>
              </div>

              <div className="pt-6 border-t border-gray-100 flex justify-between items-center">
                <div className="text-slate-500">
                  总计金额: <span className="font-bold text-slate-800 text-xl">¥ {items.reduce((sum, it) => sum + (it.price * it.quantity), 0).toFixed(2)}</span>
                </div>
                <div className="flex gap-4">
                  <button 
                    onClick={() => setEntryMode('ai')}
                    className="px-6 py-2.5 bg-gray-100 text-slate-700 rounded-xl font-bold hover:bg-gray-200 transition-all"
                  >
                    重新扫描
                  </button>
                  <button 
                    onClick={handleSave}
                    className="px-10 py-2.5 bg-emerald-600 text-white rounded-xl font-bold shadow-lg hover:bg-emerald-700 transition-all flex items-center gap-2"
                  >
                    <CheckCircle size={20} /> 完成录入
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Search, Plus, Minus, ArrowRight, Filter, Download } from 'lucide-react';
import { InventoryItem, Category } from '../types';
import { CATEGORIES } from '../constants';

interface InventoryListProps {
  inventory: InventoryItem[];
  onUpdateStock: (id: string, amount: number) => void;
}

export default function InventoryList({ inventory, onUpdateStock }: InventoryListProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('全部');

  const filteredItems = inventory.filter(item => {
    const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase());
