import React, { useState, useRef } from 'react';
import { Camera, FileUp, Plus, Trash2, CheckCircle, Loader2, X } from 'lucide-react';
import { scanDeliveryNote } from '../services/gemini';
import { Vendor, InventoryItem, DeliveryNote, DeliveryItem, Category } from '../types';
import { CATEGORIES, UNITS } from '../constants';

interface InventoryEntryProps {
  vendors: Vendor[];
  inventory: InventoryItem[];
  onComplete: (note: DeliveryNote) => void;
}

export default function InventoryEntry({ vendors, inventory, onComplete }: InventoryEntryProps) {
  const [entryMode, setEntryMode] = useState<'ai' | 'review'>('ai');
  const [isLoading, setIsLoading] = useState(false);
  const [vendorId, setVendorId] = useState('');
  const [items, setItems] = useState<DeliveryItem[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsLoading(true);
    try {
      const reader = new FileReader();
      reader.onload = async () => {
        const base64 = (reader.result as string).split(',')[1];
        const result = await scanDeliveryNote(base64);
        const foundVendor = vendors.find(v => v.name.includes(result.vendorName) || result.vendorName.includes(v.name));
        if (foundVendor) setVendorId(foundVendor.id);
        setItems(result.items.map((it: any) => ({
          name: it.name,
          quantity: it.quantity,
          unit: it.unit,
          category: it.category as Category,
          price: it.price || 0
        })));
        setEntryMode('review');
      };
      reader.readAsDataURL(file);
    } catch (error) {
      alert("识别失败，请重试");
    } finally {
      setIsLoading(false);
    }
  };

  const updateItem = (idx: number, updates: Partial<DeliveryItem>) => {
    const newItems = [...items];
    newItems[idx] = { ...newItems[idx], ...updates };
    setItems(newItems);
  };

  const removeItem = (idx: number) => {
    setItems(items.filter((_, i) => i !== idx));
  };

  const handleSave = () => {
    if (!vendorId) {
      alert("请选择供应商");
      return;
    }
    const vendor = vendors.find(v => v.id === vendorId);
    onComplete({
      id: `dn-${Date.now()}`,
      vendorId,
      vendorName: vendor?.name || '未知',
      date: new Date().toISOString().split('T')[0],
      items,
      status: 'completed'
    });
  };

  if (entryMode === 'ai') {
    return (
      <div className="flex flex-col items-center justify-center min-h-[70vh] space-y-8 animate-in zoom-in-95 duration-300">
        <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 shadow-inner">
          <Camera size={48} />
        </div>
        <div className="text-center px-6">
          <h3 className="text-xl font-black text-slate-800">拍照智能识单</h3>
          <p className="text-slate-500 text-sm mt-2 leading-relaxed">
            对准送货单拍照，AI 将自动提取供应商信息及菜品详情，无需手动录入。
          </p>
        </div>
        <div className="w-full space-y-3 px-4">
          <button 
            onClick={() => fileInputRef.current?.click()}
            disabled={isLoading}
            className="w-full py-4 bg-emerald-600 text-white rounded-2xl font-bold text-lg shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2"
          >
            {isLoading ? <Loader2 className="animate-spin" /> : <Camera size={24} />}
            {isLoading ? '正在智能识别...' : '立即拍照 / 上传'}
          </button>
          <button 
            onClick={() => setEntryMode('review')}
            className="w-full py-4 bg-white text-slate-600 rounded-2xl font-bold border border-gray-200 active:bg-gray-50"
          >
            手动录入
          </button>
        </div>
        <input type="file" className="hidden" ref={fileInputRef} accept="image/*" onChange={handleFileUpload} />
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-20 animate-in slide-in-from-right-4 duration-300">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-bold text-slate-800">确认单据信息</h3>
        <button onClick={() => setEntryMode('ai')} className="text-emerald-600 text-xs font-bold">重新扫描</button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm space-y-4">
        <div>
          <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">送货供应商</label>
          <select 
            value={vendorId}
            onChange={(e) => setVendorId(e.target.value)}
            className="w-full mt-1 p-2 bg-gray-50 border-none rounded-lg text-sm font-bold text-slate-700 outline-none"
          >
            <option value="">点击选择供应商</option>
            {vendors.map(v => <option key={v.id} value={v.id}>{v.name}</option>)}
          </select>
        </div>
      </div>

      <div className="space-y-3">
        <div className="flex items-center justify-between px-1">
          <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">清单内容 ({items.length})</label>
          <button onClick={() => setItems([...items, { name: '', quantity: 1, unit: 'kg', category: Category.OTHER, price: 0 }])} className="text-emerald-600">
            <Plus size={18} />
          </button>
        </div>

        {items.map((item, idx) => (
          <div key={idx} className="bg-white p-3 rounded-2xl border border-gray-100 shadow-sm space-y-3 relative overflow-hidden">
            <button onClick={() => removeItem(idx)} className="absolute top-3 right-3 text-slate-300 hover:text-red-500">
              <X size={16} />
            </button>
            <input 
              type="text" 
              value={item.name} 
              placeholder="商品名称"
              onChange={(e) => updateItem(idx, { name: e.target.value })}
              className="w-[85%] font-bold text-slate-800 border-none p-0 focus:ring-0 text-sm"
            />
            <div className="flex items-center gap-3">
              <div className="flex-1 bg-gray-50 p-2 rounded-lg">
                <p className="text-[8px] text-slate-400">数量</p>
                <input 
                  type="number" 
                  value={item.quantity} 
                  onChange={(e) => updateItem(idx, { quantity: parseFloat(e.target.value) })}
                  className="w-full bg-transparent border-none p-0 text-xs font-bold text-slate-700 focus:ring-0"
                />
              </div>
              <div className="flex-1 bg-gray-50 p-2 rounded-lg">
                <p className="text-[8px] text-slate-400">单位</p>
                <select 
                  value={item.unit}
                  onChange={(e) => updateItem(idx, { unit: e.target.value })}
                  className="w-full bg-transparent border-none p-0 text-xs font-bold text-slate-700 focus:ring-0"
                >
                  {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                </select>
              </div>
              <div className="flex-[1.5] bg-gray-50 p-2 rounded-lg">
                <p className="text-[8px] text-slate-400">品类</p>
                <select 
                  value={item.category}
                  onChange={(e) => updateItem(idx, { category: e.target.value as Category })}
                  className="w-full bg-transparent border-none p-0 text-xs font-bold text-slate-700 focus:ring-0"
                >
                  {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
            </div>
          </div>
        ))}
      </div>

      <div className="fixed bottom-24 left-4 right-4 max-w-md mx-auto">
        <button 
          onClick={handleSave}
          className="w-full py-4 bg-emerald-600 text-white rounded-2xl font-bold shadow-xl flex items-center justify-center gap-2 active:scale-95 transition-all"
        >
          <CheckCircle size={20} />
          完成入库
        </button>
      </div>
    </div>
  );
}

