const INITIAL_VENDORS: Vendor[] = [
  { id: 'v1', name: '兴隆蔬菜批发', contact: '张老板', phone: '13800138000', address: '新发地市场A区', categories: [Category.VEGETABLE, Category.FRUIT], paymentMethod: '周结' },
  { id: 'v2', name: '诚顺肉品供应', contact: '王经理', phone: '13900139000', address: '新发地市场B区', categories: [Category.MEAT], paymentMethod: '日结' },
];

const INITIAL_INVENTORY: InventoryItem[] = [
  { id: 'i1', name: '大白菜', category: Category.VEGETABLE, unit: 'kg', price: 2.5, currentStock: 45, minStock: 50, lastRestockDate: '2023-11-20' },
  { id: 'i2', name: '猪里脊', category: Category.MEAT, unit: 'kg', price: 32, currentStock: 12, minStock: 10, lastRestockDate: '2023-11-22' },
  { id: 'i3', name: '青岛啤酒', category: Category.BEVERAGE, unit: '箱', price: 48, currentStock: 5, minStock: 10, lastRestockDate: '2023-10-15' },
];

export default function App() {
  const [activeTab, setActiveTab] = useState('inventory');
  const [vendors, setVendors] = useState<Vendor[]>(INITIAL_VENDORS);
  const [inventory, setInventory] = useState<InventoryItem[]>(INITIAL_INVENTORY);
  const [deliveryNotes, setDeliveryNotes] = useState<DeliveryNote[]>([]);
  const [auditRecords, setAuditRecords] = useState<AuditRecord[]>([]);

  const handleUpdateStock = (itemId: string, amount: number) => {
    setInventory(prev => prev.map(item => 
      item.id === itemId ? { ...item, currentStock: Math.max(0, item.currentStock + amount) } : item
    ));
  };

  const handleSaveAudit = (record: AuditRecord) => {
    setAuditRecords(prev => [record, ...prev]);
    // Update main inventory stock
    setInventory(prev => prev.map(item => {
      const auditItem = record.items.find(ai => ai.itemId === item.id);
      if (auditItem) {
        return { ...item, currentStock: auditItem.newStock };
      }
      return item;
    }));
    setActiveTab('inventory');
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'inventory': return <InventoryList inventory={inventory} onUpdateStock={handleUpdateStock} />;
      case 'audit': return (
        <AuditManager 
          inventory={inventory} 
          auditRecords={auditRecords} 
          onSave={handleSaveAudit} 
        />
      );
      case 'delivery': return (
        <InventoryEntry 
          vendors={vendors} 
          inventory={inventory}
          onComplete={(note) => {
            setDeliveryNotes(prev => [note, ...prev]);
            const updatedInventory = [...inventory];
            note.items.forEach(item => {
              const existing = updatedInventory.find(i => i.name === item.name);
              if (existing) {
                existing.currentStock += item.quantity;
                existing.lastRestockDate = note.date;
              } else {
                updatedInventory.push({
                  id: `i-${Date.now()}-${Math.random()}`,
                  name: item.name,
                  category: item.category,
                  unit: item.unit,
                  price: item.price,
                  currentStock: item.quantity,
                  minStock: 10,
                  lastRestockDate: note.date
                });
              }
            });
            setInventory(updatedInventory);
            setActiveTab('inventory');
          }}
        />
      );
      case 'vendors': return <VendorManagement vendors={vendors} onAddVendor={(v) => setVendors([...vendors, v])} />;
      default: return <InventoryList inventory={inventory} onUpdateStock={handleUpdateStock} />;
    }
  };

  return (
    <div className="flex flex-col h-screen bg-gray-50 max-w-md mx-auto shadow-2xl overflow-hidden border-x border-gray-200">
      <header className="sticky top-0 z-30 bg-white/80 backdrop-blur-md border-b border-gray-100 px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-emerald-600 rounded-lg flex items-center justify-center text-white font-bold text-sm">餐</div>
          <h1 className="font-bold text-lg text-slate-800">餐管家</h1>
        </div>
        <div className="flex items-center gap-3">
          <button className="relative p-2 text-slate-600 active:bg-gray-100 rounded-full transition-colors">
            <Bell size={20} />
          </button>
          <div className="w-8 h-8 bg-emerald-100 text-emerald-700 rounded-full flex items-center justify-center overflow-hidden">
            <User size={18} />
          </div>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto pb-24 scroll-smooth">
        <div className="p-4">
          {renderContent()}
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white border-t border-gray-100 px-6 py-2 flex items-center justify-between z-40 shadow-[0_-4px_20px_-5px_rgba(0,0,0,0.1)]">
        {NAV_ITEMS.map(item => (
          <button
            key={item.id}
            onClick={() => setActiveTab(item.id)}
            className={`flex flex-col items-center justify-center transition-all ${item.isCenter ? 'relative -top-4' : ''} ${
              activeTab === item.id ? 'text-emerald-600' : 'text-slate-400'
            }`}
          >
            <div className={`${item.isCenter ? 'w-14 h-14 bg-emerald-600 rounded-full flex items-center justify-center text-white shadow-lg border-4 border-white active:scale-95' : ''}`}>
              {item.icon}
            </div>
            {!item.isCenter && <span className="text-[10px] mt-1 font-medium">{item.label}</span>}
          </button>
        ))}
      </footer>
    </div>
  );
}

import React, { useState } from 'react';
import { ClipboardList, Utensils, Search, CheckCircle, History, ChevronRight } from 'lucide-react';
import { InventoryItem, AuditRecord, AuditType } from '../types';

interface AuditManagerProps {
  inventory: InventoryItem[];
  auditRecords: AuditRecord[];
  onSave: (record: AuditRecord) => void;
}

export default function AuditManager({ inventory, auditRecords, onSave }: AuditManagerProps) {
  const [view, setView] = useState<'audit' | 'consumption' | 'query'>('audit');
  const [editStates, setEditStates] = useState<Record<string, number>>({});

  const handleInputChange = (id: string, value: string) => {
    const num = parseFloat(value);
    setEditStates(prev => ({ ...prev, [id]: isNaN(num) ? 0 : num }));
  };

  const submit = (type: AuditType) => {
    const items = inventory
      .filter(item => editStates[item.id] !== undefined)
      .map(item => ({
        itemId: item.id,
        itemName: item.name,
        previousStock: item.currentStock,
        newStock: type === 'DAILY_AUDIT' 
          ? editStates[item.id] 
          : Math.max(0, item.currentStock - editStates[item.id]),
        diff: type === 'DAILY_AUDIT' 
          ? editStates[item.id] - item.currentStock 
          : -editStates[item.id]
      }));

    if (items.length === 0) {
      alert("请至少输入一项盘点数据");
      return;
    }

    const record: AuditRecord = {
      id: `audit-${Date.now()}`,
      date: new Date().toLocaleString(),
      type,
      items
    };

    onSave(record);
    setEditStates({});
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-10">
      {/* Sub Tabs */}
      <div className="flex bg-white p-1 rounded-2xl border border-gray-100 shadow-sm">
        <button 
          onClick={() => setView('audit')}
          className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-1.5 ${view === 'audit' ? 'bg-emerald-600 text-white' : 'text-slate-500'}`}
        >
          <ClipboardList size={14} /> 每日盘点
        </button>
        <button 
          onClick={() => setView('consumption')}
          className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-1.5 ${view === 'consumption' ? 'bg-emerald-600 text-white' : 'text-slate-500'}`}
        >
          <Utensils size={14} /> 消耗填写
        </button>
        <button 
          onClick={() => setView('query')}
          className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-1.5 ${view === 'query' ? 'bg-emerald-600 text-white' : 'text-slate-500'}`}
        >
          <Search size={14} /> 单据查询
        </button>
      </div>

      {view === 'audit' && (
        <div className="space-y-4">
          <div className="bg-emerald-50 p-4 rounded-2xl border border-emerald-100">
            <h4 className="text-emerald-800 font-bold text-sm">每日例行盘点</h4>
            <p className="text-emerald-600 text-[10px] mt-1">请输入各项食材的当前实际库存数量。</p>
          </div>
          <div className="space-y-3">
            {inventory.map(item => (
              <div key={item.id} className="bg-white p-4 rounded-2xl border border-gray-100 flex items-center justify-between">
                <div>
                  <p className="font-bold text-slate-800 text-sm">{item.name}</p>
                  <p className="text-[10px] text-slate-400">系统账面：{item.currentStock}{item.unit}</p>
                </div>
                <div className="flex items-center gap-2">
                  <input 
                    type="number" 
                    placeholder="实际数"
                    value={editStates[item.id] ?? ''}
                    onChange={(e) => handleInputChange(item.id, e.target.value)}
                    className="w-24 text-right px-3 py-1.5 bg-gray-50 border-none rounded-lg text-sm font-bold text-emerald-600 focus:ring-2 focus:ring-emerald-500"
                  />
                  <span className="text-xs text-slate-400 font-medium">{item.unit}</span>
                </div>
              </div>
            ))}
          </div>
          <button 
            onClick={() => submit('DAILY_AUDIT')}
            className="w-full py-4 bg-emerald-600 text-white rounded-2xl font-bold shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2"
          >
            <CheckCircle size={20} /> 提交盘点结果
          </button>
        </div>
      )}

      {view === 'consumption' && (
        <div className="space-y-4">
          <div className="bg-orange-50 p-4 rounded-2xl border border-orange-100">
            <h4 className="text-orange-800 font-bold text-sm">消耗情况填写</h4>
            <p className="text-orange-600 text-[10px] mt-1">记录非正常损耗或厨房领用数量。</p>
          </div>
          <div className="space-y-3">
            {inventory.map(item => (
              <div key={item.id} className="bg-white p-4 rounded-2xl border border-gray-100 flex items-center justify-between">
                <div>
                  <p className="font-bold text-slate-800 text-sm">{item.name}</p>
                  <p className="text-[10px] text-slate-400">可用：{item.currentStock}{item.unit}</p>
                </div>
                <div className="flex items-center gap-2">
                  <input 
                    type="number" 
                    placeholder="消耗量"
                    value={editStates[item.id] ?? ''}
                    onChange={(e) => handleInputChange(item.id, e.target.value)}
                    className="w-24 text-right px-3 py-1.5 bg-gray-50 border-none rounded-lg text-sm font-bold text-orange-600 focus:ring-2 focus:ring-orange-500"
                  />
                  <span className="text-xs text-slate-400 font-medium">{item.unit}</span>
                </div>
              </div>
            ))}
          </div>
          <button 
            onClick={() => submit('CONSUMPTION')}
            className="w-full py-4 bg-orange-600 text-white rounded-2xl font-bold shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2"
          >
            <CheckCircle size={20} /> 提交消耗记录
          </button>
        </div>
      )}

      {view === 'query' && (
        <div className="space-y-3">
          {auditRecords.length > 0 ? auditRecords.map(record => (
            <div key={record.id} className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm active:bg-gray-50 transition-colors">
              <div className="flex justify-between items-start mb-2">
                <div className="flex items-center gap-2">
                  <div className={`p-1.5 rounded-lg ${record.type === 'DAILY_AUDIT' ? 'bg-emerald-50 text-emerald-600' : 'bg-orange-50 text-orange-600'}`}>
                    {record.type === 'DAILY_AUDIT' ? <ClipboardList size={16} /> : <Utensils size={16} />}
                  </div>
                  <div>
                    <h5 className="text-sm font-bold text-slate-800">
                      {record.type === 'DAILY_AUDIT' ? '每日盘点单' : '食材消耗单'}
                    </h5>
                    <p className="text-[10px] text-slate-400">{record.date}</p>
                  </div>
                </div>
                <ChevronRight size={16} className="text-slate-300" />
              </div>
              <div className="flex flex-wrap gap-1.5 mt-3">
                {record.items.slice(0, 3).map((it, idx) => (
                  <span key={idx} className="px-2 py-0.5 bg-gray-50 border border-gray-100 rounded text-[9px] text-slate-500 font-medium">
                    {it.itemName}: {it.diff > 0 ? '+' : ''}{it.diff}
                  </span>
                ))}
                {record.items.length > 3 && (
                  <span className="text-[9px] text-slate-300 self-center">等{record.items.length}项...</span>
                )}
              </div>
            </div>
          )) : (
            <div className="p-12 text-center">
              <div className="w-12 h-12 bg-gray-50 rounded-full flex items-center justify-center text-slate-300 mx-auto mb-3">
                <History size={24} />
              </div>
              <p className="text-slate-400 text-xs">暂无历史单据记录</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

