  'kg', 'g', '瓶', '箱', '个', '袋', '升', '斤'
];

export const NAV_ITEMS = [
  { id: 'inventory', label: '库存', icon: <Package size={22} /> },
  { id: 'delivery', label: '拍照', icon: <Camera size={28} />, isCenter: true },
