          onClick={() => setActiveSubTab('stock')}
          className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-1.5 ${activeSubTab === 'stock' ? 'bg-emerald-600 text-white' : 'text-slate-500'}`}
