                    <span key={idx} className="px-2 py-0.5 bg-gray-50 border border-gray-100 rounded text-[9px] text-slate-500 font-medium">
                      {it.itemName}: {it.diff > 0 ? '+' : ''}{it.diff}
                    </span>
                  ))}
                  {record.items.length > 3 && (
                    <span className="text-[9px] text-slate-300 self-center">等{record.items.length}项...</span>
                  )}
                </div>
              </div>
            )) : (
              <div className="p-12 text-center">
                <div className="w-12 h-12 bg-gray-50 rounded-full flex items-center justify-center text-slate-300 mx-auto mb-3">
                  <Filter size={24} />
                </div>
                <p className="text-slate-400 text-xs">暂无匹配的单据记录</p>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { Search, Plus, Minus, SlidersHorizontal, History, Package, ChevronRight, Calendar } from 'lucide-react';
import { InventoryItem, Category, DeliveryNote } from '../types';
import { CATEGORIES } from '../constants';

interface InventoryListProps {
  inventory: InventoryItem[];
  deliveryNotes: DeliveryNote[];
  onUpdateStock: (id: string, amount: number) => void;
}

export default function InventoryList({ inventory, onUpdateStock, deliveryNotes }: InventoryListProps) {
  const [activeSubTab, setActiveSubTab] = useState<'stock' | 'history'>('stock');
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('全部');

  // 历史单据查询状态
  const [historySearchVendor, setHistorySearchVendor] = useState('');
  const [historySearchDate, setHistorySearchDate] = useState('');

  const filteredItems = inventory.filter(item => {
    const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = filterCategory === '全部' || item.category === filterCategory;
    return matchesSearch && matchesCategory;
  });

  const filteredHistory = deliveryNotes.filter(note => {
    const matchesVendor = note.vendorName.toLowerCase().includes(historySearchVendor.toLowerCase());
    const matchesDate = historySearchDate === '' || note.date.startsWith(historySearchDate);
    return matchesVendor && matchesDate;
  });

  return (
    <div className="space-y-4 animate-in fade-in duration-500 pb-10">
      {/* Sub Tabs */}
      <div className="flex bg-white p-1 rounded-2xl border border-gray-100 shadow-sm mb-2">
        <button 
          onClick={() => setActiveSubTab('stock')}
          className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-1.5 ${activeSubTab === 'stock' ? 'bg-emerald-600 text-white' : 'text-slate-500'}`}
        >
          <Package size={14} /> 实时库存
        </button>
        <button 
          onClick={() => setActiveSubTab('history')}
          className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-1.5 ${activeSubTab === 'history' ? 'bg-emerald-600 text-white' : 'text-slate-500'}`}
        >
          <History size={14} /> 单据查询
        </button>
      </div>

      {activeSubTab === 'stock' ? (
        <>
          <div className="flex items-center gap-2">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
              <input 
                type="text" 
                placeholder="搜索食材..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-9 pr-4 py-2.5 bg-white border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-emerald-500 shadow-sm outline-none"
              />
            </div>
            <button className="p-2.5 bg-white border border-gray-200 rounded-xl text-slate-600 shadow-sm active:bg-gray-50">
              <SlidersHorizontal size={20} />
            </button>
          </div>

          <div className="flex overflow-x-auto gap-2 py-1 no-scrollbar">
            <button 
              onClick={() => setFilterCategory('全部')}
              className={`whitespace-nowrap px-4 py-1.5 rounded-full text-xs font-bold transition-all ${
                filterCategory === '全部' ? 'bg-emerald-600 text-white' : 'bg-white text-slate-500 border border-gray-100'
              }`}
            >
              全部
            </button>
            {CATEGORIES.map(c => (
              <button 
                key={c}
                onClick={() => setFilterCategory(c)}
                className={`whitespace-nowrap px-4 py-1.5 rounded-full text-xs font-bold transition-all ${
                  filterCategory === c ? 'bg-emerald-600 text-white' : 'bg-white text-slate-500 border border-gray-100'
                }`}
              >
                {c}
              </button>
            ))}
          </div>

          <div className="grid grid-cols-1 gap-3">
            {filteredItems.map((item) => {
              const isLow = item.currentStock < item.minStock;
              return (
                <div key={item.id} className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm active:scale-[0.98] transition-transform">
                  <div className="flex justify-between items-start mb-3">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-emerald-50 text-emerald-600 rounded-xl flex items-center justify-center font-bold">
                        {item.name.charAt(0)}
                      </div>
                      <div>
                        <h4 className="font-bold text-slate-800 text-sm">{item.name}</h4>
                        <p className="text-[10px] text-slate-400">{item.category} · 警戒:{item.minStock}{item.unit}</p>
                      </div>
                    </div>
                    {isLow && (
                      <span className="px-2 py-0.5 bg-red-50 text-red-600 text-[10px] font-bold rounded">缺货</span>
                    )}
                  </div>

                  <div className="flex items-center justify-between">
                    <div className="flex items-baseline gap-1">
                      <span className={`text-xl font-black ${isLow ? 'text-red-500' : 'text-emerald-600'}`}>
                        {item.currentStock}
                      </span>
                      <span className="text-xs text-slate-400">{item.unit}</span>
                    </div>

                    <div className="flex items-center gap-2">
                      <button 
                        onClick={() => onUpdateStock(item.id, -1)}
                        className="w-9 h-9 flex items-center justify-center bg-gray-50 rounded-xl text-slate-600 active:bg-gray-200 transition-colors"
                      >
                        <Minus size={16} />
                      </button>
                      <button 
                        onClick={() => onUpdateStock(item.id, 1)}
                        className="w-9 h-9 flex items-center justify-center bg-emerald-50 rounded-xl text-emerald-600 active:bg-emerald-100 transition-colors"
                      >
                        <Plus size={16} />
                      </button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </>
      ) : (
        <div className="space-y-4">
          {/* 历史单据查询筛选器 */}
          <div className="grid grid-cols-2 gap-2">
            <div className="relative">
              <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
              <input 
                type="text" 
                placeholder="供应商" 
                value={historySearchVendor}
                onChange={(e) => setHistorySearchVendor(e.target.value)}
                className="w-full pl-8 pr-3 py-2 bg-white border border-gray-200 rounded-xl text-xs focus:ring-2 focus:ring-emerald-500 outline-none"
              />
            </div>
            <div className="relative">
              <Calendar className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
              <input 
                type="date" 
                value={historySearchDate}
                onChange={(e) => setHistorySearchDate(e.target.value)}
                className="w-full pl-8 pr-3 py-2 bg-white border border-gray-200 rounded-xl text-xs focus:ring-2 focus:ring-emerald-500 outline-none"
              />
            </div>
          </div>

          <div className="space-y-3">
            {filteredHistory.length > 0 ? filteredHistory.map(note => {
              const dateObj = new Date(note.date);
              // 按照 供应商名称＋时间xx月xx日 命名
              const formattedName = `${note.vendorName}${dateObj.getMonth() + 1}月${dateObj.getDate()}日`;

              return (
                <div key={note.id} className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm active:bg-gray-50 transition-colors">
                  <div className="flex justify-between items-start">
                    <div>
                      <h5 className="text-sm font-bold text-slate-800">{formattedName}</h5>
                      <p className="text-[10px] text-slate-400 mt-1">记录时间: {dateObj.toLocaleString()}</p>
                      <div className="flex flex-wrap gap-1.5 mt-2">
                        {note.items.slice(0, 3).map((it, idx) => (
                          <span key={idx} className="px-2 py-0.5 bg-gray-50 border border-gray-100 rounded text-[9px] text-slate-500">
                            {it.name} x{it.quantity}
                          </span>
                        ))}
                        {note.items.length > 3 && <span className="text-[9px] text-slate-300 self-center">...等{note.items.length}项</span>}
                      </div>
                    </div>
                    <ChevronRight size={16} className="text-slate-300" />
                  </div>
                </div>
              );
            }) : (
              <div className="p-12 text-center">
                <div className="w-12 h-12 bg-gray-50 rounded-full flex items-center justify-center text-slate-300 mx-auto mb-3">
                  <History size={24} />
                </div>
                <p className="text-slate-400 text-xs">暂无匹配的入库单据</p>
              </div>
            )}
          </div>
        </div>
      )}

      {activeSubTab === 'stock' && filteredItems.length === 0 && (
        <div className="p-12 text-center">
          <p className="text-slate-400 text-sm">没有找到相关食材</p>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { ClipboardList, Utensils, Search, CheckCircle, History, ChevronRight, Calendar, Filter, Trash2, Plus, X } from 'lucide-react';
import { InventoryItem, AuditRecord, AuditType } from '../types';

interface AuditManagerProps {
  inventory: InventoryItem[];
  auditRecords: AuditRecord[];
  onSave: (record: AuditRecord) => void;
}

const CONSUMPTION_TYPES = ['老板带走', '员工餐', '试菜', '临时菜'];

export default function AuditManager({ inventory, auditRecords, onSave }: AuditManagerProps) {
  const [view, setView] = useState<'audit' | 'consumption' | 'query'>('audit');
  const [editStates, setEditStates] = useState<Record<string, number>>({});
  const [selectedConsumptionType, setSelectedConsumptionType] = useState('员工餐');

  // 盘点列表管理
  const [visibleAuditIds, setVisibleAuditIds] = useState<string[]>([]);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [showAddModal, setShowAddModal] = useState(false);

  // 初始化盘点列表（默认显示全部）
  useEffect(() => {
    setVisibleAuditIds(inventory.map(i => i.id));
  }, [inventory]);

  // 筛选状态
  const [searchDate, setSearchDate] = useState('');
  const [filterType, setFilterType] = useState<'ALL' | 'DAILY_AUDIT' | 'CONSUMPTION'>('ALL');

  const handleInputChange = (id: string, value: string) => {
    const num = parseFloat(value);
    setEditStates(prev => ({ ...prev, [id]: isNaN(num) ? 0 : num }));
  };

  const toggleSelect = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  const toggleSelectAll = () => {
    if (selectedIds.size === visibleAuditIds.length) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(visibleAuditIds));
    }
  };

  const batchDelete = () => {
    if (selectedIds.size === 0) return;
    setVisibleAuditIds(prev => prev.filter(id => !selectedIds.has(id)));
    setSelectedIds(new Set());
  };

  const addItemToAudit = (id: string) => {
    if (!visibleAuditIds.includes(id)) {
      setVisibleAuditIds(prev => [...prev, id]);
    }
    setShowAddModal(false);
  };

  const submit = (type: AuditType) => {
    const itemsToProcess = type === 'DAILY_AUDIT' 
      ? inventory.filter(i => visibleAuditIds.includes(i.id))
      : inventory;

    const items = itemsToProcess
      .filter(item => editStates[item.id] !== undefined && editStates[item.id] !== 0)
      .map(item => ({
        itemId: item.id,
        itemName: item.name,
        previousStock: item.currentStock,
        newStock: type === 'DAILY_AUDIT' 
          ? editStates[item.id] 
          : Math.max(0, item.currentStock - editStates[item.id]),
        diff: type === 'DAILY_AUDIT' 
          ? editStates[item.id] - item.currentStock 
          : -editStates[item.id]
      }));

    if (items.length === 0) {
      alert("请至少输入一项有效数据");
      return;
    }

    const record: AuditRecord = {
      id: `audit-${Date.now()}`,
      date: new Date().toISOString(),
      type,
      consumptionType: type === 'CONSUMPTION' ? selectedConsumptionType : undefined,
      items
    };

    onSave(record);
    setEditStates({});
    setSelectedIds(new Set());
  };

  const filteredAuditRecords = auditRecords.filter(record => {
    const dateMatch = searchDate === '' || record.date.startsWith(searchDate);
    const typeMatch = filterType === 'ALL' || record.type === filterType;
    return dateMatch && typeMatch;
  });

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-10">
      {/* Sub Tabs */}
      <div className="flex bg-white p-1 rounded-2xl border border-gray-100 shadow-sm">
        <button 
          onClick={() => setView('audit')}
          className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-1.5 ${view === 'audit' ? 'bg-emerald-600 text-white' : 'text-slate-500'}`}
        >
          <ClipboardList size={14} /> 每日盘点
        </button>
        <button 
          onClick={() => setView('consumption')}
          className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-1.5 ${view === 'consumption' ? 'bg-emerald-600 text-white' : 'text-slate-500'}`}
        >
          <Utensils size={14} /> 消耗填写
        </button>
        <button 
          onClick={() => setView('query')}
          className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-1.5 ${view === 'query' ? 'bg-emerald-600 text-white' : 'text-slate-500'}`}
        >
          <Search size={14} /> 单据查询
        </button>
      </div>

      {view === 'audit' && (
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <div className="bg-emerald-50 px-4 py-3 rounded-2xl border border-emerald-100 flex-1 mr-3">
              <h4 className="text-emerald-800 font-bold text-sm">当前待盘点项</h4>
              <p className="text-emerald-600 text-[10px] mt-1">勾选并录入实存，未填写的项将不会被更新。</p>
            </div>
            {selectedIds.size > 0 && (
              <button 
                onClick={batchDelete}
                className="p-3 bg-red-50 text-red-600 rounded-2xl border border-red-100 shadow-sm active:scale-95 transition-all flex items-center gap-2"
              >
                <Trash2 size={18} />
                <span className="text-xs font-bold">{selectedIds.size}</span>
              </button>
            )}
          </div>

          <div className="flex items-center gap-2 px-1 mb-1">
             <button 
                onClick={toggleSelectAll}
                className="text-[10px] font-bold text-slate-400 hover:text-emerald-600 transition-colors"
             >
               {selectedIds.size === visibleAuditIds.length ? '取消全选' : '全选项'}
             </button>
          </div>

          <div className="space-y-3">
            {inventory.filter(i => visibleAuditIds.includes(i.id)).map(item => (
              <div key={item.id} className={`bg-white p-4 rounded-2xl border transition-all flex items-center gap-3 ${selectedIds.has(item.id) ? 'border-emerald-500 bg-emerald-50/30' : 'border-gray-100'}`}>
                <input 
                  type="checkbox" 
                  checked={selectedIds.has(item.id)}
                  onChange={() => toggleSelect(item.id)}
                  className="w-5 h-5 rounded-lg border-gray-300 text-emerald-600 focus:ring-emerald-500"
                />
                <div className="flex-1">
                  <p className="font-bold text-slate-800 text-sm">{item.name}</p>
                  <p className="text-[10px] text-slate-400">账面：{item.currentStock}{item.unit}</p>
                </div>
                <div className="flex items-center gap-2">
                  <input 
                    type="number" 
                    placeholder="实存"
                    value={editStates[item.id] ?? ''}
                    onChange={(e) => handleInputChange(item.id, e.target.value)}
                    className="w-20 text-right px-2 py-1.5 bg-gray-50 border-none rounded-lg text-sm font-bold text-emerald-600 focus:ring-2 focus:ring-emerald-500"
                  />
                  <span className="text-xs text-slate-400 font-medium">{item.unit}</span>
                </div>
              </div>
            ))}

            {/* 新增盘点项按钮 */}
            <button 
              onClick={() => setShowAddModal(true)}
              className="w-full py-4 border-2 border-dashed border-gray-200 rounded-2xl text-slate-400 flex items-center justify-center gap-2 hover:border-emerald-300 hover:text-emerald-500 transition-all active:scale-[0.98]"
            >
              <Plus size={20} />
              <span className="text-sm font-bold">增加一行/新增食材</span>
            </button>
          </div>

          <button 
            onClick={() => submit('DAILY_AUDIT')}
            className="w-full py-4 bg-emerald-600 text-white rounded-2xl font-bold shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2"
          >
            <CheckCircle size={20} /> 提交盘点结果
          </button>
        </div>
      )}

      {view === 'consumption' && (
        <div className="space-y-4">
          <div className="bg-orange-50 p-4 rounded-2xl border border-orange-100">
            <h4 className="text-orange-800 font-bold text-sm">消耗情况填写</h4>
            <p className="text-orange-600 text-[10px] mt-1">记录非正常损耗、员工餐或试菜领用数量。</p>
          </div>

          <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm">
            <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3 block">消耗类型</label>
            <div className="flex flex-wrap gap-2">
              {CONSUMPTION_TYPES.map(type => (
                <button
                  key={type}
                  onClick={() => setSelectedConsumptionType(type)}
                  className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all border ${
                    selectedConsumptionType === type 
                      ? 'bg-orange-600 text-white border-orange-600 shadow-sm' 
                      : 'bg-white text-slate-500 border-gray-100'
                  }`}
                >
                  {type}
                </button>
              ))}
            </div>
          </div>

          <div className="space-y-3">
            {inventory.map(item => (
              <div key={item.id} className="bg-white p-4 rounded-2xl border border-gray-100 flex items-center justify-between">
                <div>
                  <p className="font-bold text-slate-800 text-sm">{item.name}</p>
                  <p className="text-[10px] text-slate-400">可用：{item.currentStock}{item.unit}</p>
                </div>
                <div className="flex items-center gap-2">
                  <input 
                    type="number" 
                    placeholder="消耗量"
                    value={editStates[item.id] ?? ''}
                    onChange={(e) => handleInputChange(item.id, e.target.value)}
                    className="w-24 text-right px-3 py-1.5 bg-gray-50 border-none rounded-lg text-sm font-bold text-orange-600 focus:ring-2 focus:ring-orange-500"
                  />
                  <span className="text-xs text-slate-400 font-medium">{item.unit}</span>
                </div>
              </div>
            ))}
          </div>
          <button 
            onClick={() => submit('CONSUMPTION')}
            className="w-full py-4 bg-orange-600 text-white rounded-2xl font-bold shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2"
          >
            <CheckCircle size={20} /> 提交消耗记录
          </button>
        </div>
      )}

      {view === 'query' && (
        <div className="space-y-4">
          <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm space-y-4">
            <div className="relative">
              <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
              <input 
                type="date" 
                value={searchDate}
                onChange={(e) => setSearchDate(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
              />
            </div>

            <div className="flex gap-2">
              <button
                onClick={() => setFilterType('ALL')}
                className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all border ${
                  filterType === 'ALL' ? 'bg-slate-800 text-white border-slate-800' : 'bg-white text-slate-500 border-gray-100'
                }`}
              >
                全部单据
              </button>
              <button
                onClick={() => setFilterType('DAILY_AUDIT')}
                className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all border ${
                  filterType === 'DAILY_AUDIT' ? 'bg-emerald-600 text-white border-emerald-600' : 'bg-white text-slate-500 border-gray-100'
                }`}
              >
                盘点单据
              </button>
              <button
                onClick={() => setFilterType('CONSUMPTION')}
                className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all border ${
                  filterType === 'CONSUMPTION' ? 'bg-orange-600 text-white border-orange-600' : 'bg-white text-slate-500 border-gray-100'
                }`}
              >
                消耗单据
              </button>
            </div>
          </div>

          <div className="space-y-3">
            {filteredAuditRecords.length > 0 ? filteredAuditRecords.map(record => (
              <div key={record.id} className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm active:bg-gray-50 transition-colors">
                <div className="flex justify-between items-start mb-2">
                  <div className="flex items-center gap-2">
                    <div className={`p-1.5 rounded-lg ${record.type === 'DAILY_AUDIT' ? 'bg-emerald-50 text-emerald-600' : 'bg-orange-50 text-orange-600'}`}>
                      {record.type === 'DAILY_AUDIT' ? <ClipboardList size={16} /> : <Utensils size={16} />}
                    </div>
                    <div>
                      <h5 className="text-sm font-bold text-slate-800 flex items-center gap-2">
                        {record.type === 'DAILY_AUDIT' ? '盘点单据' : '消耗单据'}
                        {record.consumptionType && (
                          <span className="px-1.5 py-0.5 bg-orange-50 text-orange-600 text-[9px] border border-orange-100 rounded">
                            {record.consumptionType}
                          </span>
                        )}
                      </h5>
                      <p className="text-[10px] text-slate-400">{new Date(record.date).toLocaleString()}</p>
                    </div>
                  </div>
                  <ChevronRight size={16} className="text-slate-300" />
                </div>
                <div className="flex flex-wrap gap-1.5 mt-3">
                  {record.items.slice(0, 3).map((it, idx) => (
                    <span key={idx} className="px-2 py-0.5 bg-gray-50 border border-gray-100 rounded text-[9px] text-slate-500 font-medium">
                      {it.itemName}: {it.diff > 0 ? '+' : ''}{it.diff}
                    </span>
                  ))}
                  {record.items.length > 3 && (
                    <span className="text-[9px] text-slate-300 self-center">等{record.items.length}项...</span>
                  )}
                </div>
              </div>
            )) : (
              <div className="p-12 text-center">
                <div className="w-12 h-12 bg-gray-50 rounded-full flex items-center justify-center text-slate-300 mx-auto mb-3">
                  <Filter size={24} />
                </div>
                <p className="text-slate-400 text-xs">暂无匹配的单据记录</p>
              </div>
            )}
          </div>
        </div>
      )}

      {/* 新增项 Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-sm rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[80vh]">
            <div className="p-4 border-b border-gray-100 flex items-center justify-between">
              <h4 className="font-bold text-slate-800">添加盘点食材</h4>
              <button onClick={() => setShowAddModal(false)} className="p-1.5 bg-gray-50 rounded-full text-slate-400">
                <X size={18} />
              </button>
            </div>
            <div className="flex-1 overflow-y-auto p-2 space-y-1">
              {inventory
                .filter(item => !visibleAuditIds.includes(item.id))
                .map(item => (
                  <button 
                    key={item.id}
                    onClick={() => addItemToAudit(item.id)}
                    className="w-full p-3 flex items-center justify-between hover:bg-gray-50 rounded-2xl transition-colors text-left"
                  >
                    <div>
                      <p className="text-sm font-bold text-slate-700">{item.name}</p>
                      <p className="text-[10px] text-slate-400">{item.category} · 当前库存:{item.currentStock}{item.unit}</p>
                    </div>
                    <div className="p-1.5 bg-emerald-50 text-emerald-600 rounded-lg">
                      <Plus size={16} />
                    </div>
                  </button>
                ))}
              {inventory.filter(item => !visibleAuditIds.includes(item.id)).length === 0 && (
                <div className="p-8 text-center text-slate-400 text-xs">
                  所有库存食材已在盘点列表中
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { ClipboardList, Utensils, Search, CheckCircle, History, ChevronRight, Calendar, Filter, Trash2, Plus, X } from 'lucide-react';
import { InventoryItem, AuditRecord, AuditType } from '../types';

interface AuditManagerProps {
  inventory: InventoryItem[];
  auditRecords: AuditRecord[];
  onSave: (record: AuditRecord) => void;
}

const CONSUMPTION_TYPES = ['老板带走', '员工餐', '试菜', '临时菜'];

export default function AuditManager({ inventory, auditRecords, onSave }: AuditManagerProps) {
  const [view, setView] = useState<'audit' | 'consumption' | 'query'>('audit');
  const [editStates, setEditStates] = useState<Record<string, number>>({});
  const [selectedConsumptionType, setSelectedConsumptionType] = useState('员工餐');

  // 列表管理
  const [visibleAuditIds, setVisibleAuditIds] = useState<string[]>([]);
  const [visibleConsumptionIds, setVisibleConsumptionIds] = useState<string[]>([]);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [showAddModal, setShowAddModal] = useState(false);

  // 初始化列表（默认显示全部）
  useEffect(() => {
    const allIds = inventory.map(i => i.id);
    setVisibleAuditIds(allIds);
    setVisibleConsumptionIds(allIds);
  }, [inventory]);

  // 当切换视图时，清空选择状态
  useEffect(() => {
    setSelectedIds(new Set());
  }, [view]);

  // 筛选状态
  const [searchDate, setSearchDate] = useState('');
  const [filterType, setFilterType] = useState<'ALL' | 'DAILY_AUDIT' | 'CONSUMPTION'>('ALL');

  const handleInputChange = (id: string, value: string) => {
    const num = parseFloat(value);
    setEditStates(prev => ({ ...prev, [id]: isNaN(num) ? 0 : num }));
  };

  const toggleSelect = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  const currentVisibleIds = view === 'audit' ? visibleAuditIds : visibleConsumptionIds;

  const toggleSelectAll = () => {
    if (selectedIds.size === currentVisibleIds.length) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(currentVisibleIds));
    }
  };

  const batchDelete = () => {
    if (selectedIds.size === 0) return;
    if (view === 'audit') {
      setVisibleAuditIds(prev => prev.filter(id => !selectedIds.has(id)));
    } else {
      setVisibleConsumptionIds(prev => prev.filter(id => !selectedIds.has(id)));
    }
    setSelectedIds(new Set());
  };

  const addItemToView = (id: string) => {
    if (view === 'audit') {
      if (!visibleAuditIds.includes(id)) setVisibleAuditIds(prev => [...prev, id]);
    } else {
      if (!visibleConsumptionIds.includes(id)) setVisibleConsumptionIds(prev => [...prev, id]);
    }
    setShowAddModal(false);
  };

  const submit = (type: AuditType) => {
    const activeIds = type === 'DAILY_AUDIT' ? visibleAuditIds : visibleConsumptionIds;
    const itemsToProcess = inventory.filter(i => activeIds.includes(i.id));

    const items = itemsToProcess
      .filter(item => editStates[item.id] !== undefined && editStates[item.id] !== 0)
      .map(item => ({
        itemId: item.id,
        itemName: item.name,
        previousStock: item.currentStock,
        newStock: type === 'DAILY_AUDIT' 
          ? editStates[item.id] 
          : Math.max(0, item.currentStock - editStates[item.id]),
        diff: type === 'DAILY_AUDIT' 
          ? editStates[item.id] - item.currentStock 
          : -editStates[item.id]
      }));

    if (items.length === 0) {
      alert("请至少输入一项有效数据");
      return;
    }

    const record: AuditRecord = {
      id: `audit-${Date.now()}`,
      date: new Date().toISOString(),
      type,
      consumptionType: type === 'CONSUMPTION' ? selectedConsumptionType : undefined,
      items
    };

    onSave(record);
    setEditStates({});
    setSelectedIds(new Set());
  };

  const filteredAuditRecords = auditRecords.filter(record => {
    const dateMatch = searchDate === '' || record.date.startsWith(searchDate);
    const typeMatch = filterType === 'ALL' || record.type === filterType;
    return dateMatch && typeMatch;
  });

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-10">
      {/* Sub Tabs */}
      <div className="flex bg-white p-1 rounded-2xl border border-gray-100 shadow-sm">
        <button 
          onClick={() => setView('audit')}
          className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-1.5 ${view === 'audit' ? 'bg-emerald-600 text-white' : 'text-slate-500'}`}
        >
          <ClipboardList size={14} /> 每日盘点
        </button>
        <button 
          onClick={() => setView('consumption')}
          className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-1.5 ${view === 'consumption' ? 'bg-emerald-600 text-white' : 'text-slate-500'}`}
        >
          <Utensils size={14} /> 消耗填写
        </button>
        <button 
          onClick={() => setView('query')}
          className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-1.5 ${view === 'query' ? 'bg-emerald-600 text-white' : 'text-slate-500'}`}
        >
          <Search size={14} /> 单据查询
        </button>
      </div>

      {view !== 'query' && (
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <div className={`${view === 'audit' ? 'bg-emerald-50 border-emerald-100' : 'bg-orange-50 border-orange-100'} px-4 py-3 rounded-2xl border flex-1 mr-3`}>
              <h4 className={`font-bold text-sm ${view === 'audit' ? 'text-emerald-800' : 'text-orange-800'}`}>
                {view === 'audit' ? '当前待盘点项' : '当前消耗录入项'}
              </h4>
              <p className={`text-[10px] mt-1 ${view === 'audit' ? 'text-emerald-600' : 'text-orange-600'}`}>
                {view === 'audit' ? '勾选并录入实存，未填写的项将不会被更新。' : '勾选并录入消耗量。'}
              </p>
            </div>
            {selectedIds.size > 0 && (
              <button 
                onClick={batchDelete}
                className="p-3 bg-red-50 text-red-600 rounded-2xl border border-red-100 shadow-sm active:scale-95 transition-all flex items-center gap-2"
              >
                <Trash2 size={18} />
                <span className="text-xs font-bold">{selectedIds.size}</span>
              </button>
            )}
          </div>

          {view === 'consumption' && (
            <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3 block">消耗类型</label>
              <div className="flex flex-wrap gap-2">
                {CONSUMPTION_TYPES.map(type => (
                  <button
                    key={type}
                    onClick={() => setSelectedConsumptionType(type)}
                    className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all border ${
                      selectedConsumptionType === type 
                        ? 'bg-orange-600 text-white border-orange-600 shadow-sm' 
                        : 'bg-white text-slate-500 border-gray-100'
                    }`}
                  >
                    {type}
                  </button>
                ))}
              </div>
            </div>
          )}

          <div className="flex items-center gap-2 px-1 mb-1">
             <button 
                onClick={toggleSelectAll}
                className={`text-[10px] font-bold transition-colors ${selectedIds.size === currentVisibleIds.length ? 'text-emerald-600' : 'text-slate-400'}`}
             >
               {selectedIds.size === currentVisibleIds.length ? '取消全选' : '全选项'}
             </button>
          </div>

          <div className="space-y-3">
            {inventory.filter(i => currentVisibleIds.includes(i.id)).map(item => (
              <div key={item.id} className={`bg-white p-4 rounded-2xl border transition-all flex items-center gap-3 ${selectedIds.has(item.id) ? (view === 'audit' ? 'border-emerald-500 bg-emerald-50/30' : 'border-orange-500 bg-orange-50/30') : 'border-gray-100'}`}>
                <input 
                  type="checkbox" 
                  checked={selectedIds.has(item.id)}
                  onChange={() => toggleSelect(item.id)}
                  className={`w-5 h-5 rounded-lg border-gray-300 focus:ring-offset-0 ${view === 'audit' ? 'text-emerald-600 focus:ring-emerald-500' : 'text-orange-600 focus:ring-orange-500'}`}
                />
                <div className="flex-1">
                  <p className="font-bold text-slate-800 text-sm">{item.name}</p>
                  <p className="text-[10px] text-slate-400">
                    {view === 'audit' ? `账面：${item.currentStock}${item.unit}` : `可用：${item.currentStock}${item.unit}`}
                  </p>
                </div>
                <div className="flex items-center gap-2">
                  <input 
                    type="number" 
                    placeholder={view === 'audit' ? "实存" : "消耗"}
                    value={editStates[item.id] ?? ''}
                    onChange={(e) => handleInputChange(item.id, e.target.value)}
                    className={`w-20 text-right px-2 py-1.5 bg-gray-50 border-none rounded-lg text-sm font-bold focus:ring-2 ${view === 'audit' ? 'text-emerald-600 focus:ring-emerald-500' : 'text-orange-600 focus:ring-orange-500'}`}
                  />
                  <span className="text-xs text-slate-400 font-medium">{item.unit}</span>
                </div>
              </div>
            ))}

            {/* 新增行按钮 */}
            <button 
              onClick={() => setShowAddModal(true)}
              className="w-full py-4 border-2 border-dashed border-gray-200 rounded-2xl text-slate-400 flex items-center justify-center gap-2 hover:border-emerald-300 hover:text-emerald-500 transition-all active:scale-[0.98]"
            >
              <Plus size={20} />
              <span className="text-sm font-bold">增加一行/新增食材</span>
            </button>
          </div>

          <button 
            onClick={() => submit(view === 'audit' ? 'DAILY_AUDIT' : 'CONSUMPTION')}
            className={`w-full py-4 text-white rounded-2xl font-bold shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2 ${view === 'audit' ? 'bg-emerald-600 shadow-emerald-200' : 'bg-orange-600 shadow-orange-200'}`}
          >
            <CheckCircle size={20} />
            {view === 'audit' ? '提交盘点结果' : '提交消耗记录'}
          </button>
        </div>
      )}

      {view === 'query' && (
        <div className="space-y-4">
          <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm space-y-4">
            <div className="relative">
              <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
              <input 
                type="date" 
                value={searchDate}
                onChange={(e) => setSearchDate(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
              />
            </div>

            <div className="flex gap-2">
              <button
                onClick={() => setFilterType('ALL')}
                className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all border ${
                  filterType === 'ALL' ? 'bg-slate-800 text-white border-slate-800' : 'bg-white text-slate-500 border-gray-100'
                }`}
              >
                全部单据
              </button>
              <button
                onClick={() => setFilterType('DAILY_AUDIT')}
                className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all border ${
                  filterType === 'DAILY_AUDIT' ? 'bg-emerald-600 text-white border-emerald-600' : 'bg-white text-slate-500 border-gray-100'
                }`}
              >
                盘点单据
              </button>
              <button
                onClick={() => setFilterType('CONSUMPTION')}
                className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all border ${
                  filterType === 'CONSUMPTION' ? 'bg-orange-600 text-white border-orange-600' : 'bg-white text-slate-500 border-gray-100'
                }`}
              >
                消耗单据
              </button>
            </div>
          </div>

          <div className="space-y-3">
            {filteredAuditRecords.length > 0 ? filteredAuditRecords.map(record => (
              <div key={record.id} className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm active:bg-gray-50 transition-colors">
                <div className="flex justify-between items-start mb-2">
                  <div className="flex items-center gap-2">
                    <div className={`p-1.5 rounded-lg ${record.type === 'DAILY_AUDIT' ? 'bg-emerald-50 text-emerald-600' : 'bg-orange-50 text-orange-600'}`}>
                      {record.type === 'DAILY_AUDIT' ? <ClipboardList size={16} /> : <Utensils size={16} />}
                    </div>
                    <div>
                      <h5 className="text-sm font-bold text-slate-800 flex items-center gap-2">
                        {record.type === 'DAILY_AUDIT' ? '盘点单据' : '消耗单据'}
                        {record.consumptionType && (
                          <span className="px-1.5 py-0.5 bg-orange-50 text-orange-600 text-[9px] border border-orange-100 rounded">
                            {record.consumptionType}
                          </span>
                        )}
                      </h5>
                      <p className="text-[10px] text-slate-400">{new Date(record.date).toLocaleString()}</p>
                    </div>
                  </div>
                  <ChevronRight size={16} className="text-slate-300" />
                </div>
                <div className="flex flex-wrap gap-1.5 mt-3">
                  {record.items.slice(0, 3).map((it, idx) => (
                    <span key={idx} className="px-2 py-0.5 bg-gray-50 border border-gray-100 rounded text-[9px] text-slate-500 font-medium">
                      {it.itemName}: {it.diff > 0 ? '+' : ''}{it.diff}
                    </span>
                  ))}
                  {record.items.length > 3 && (
                    <span className="text-[9px] text-slate-300 self-center">等{record.items.length}项...</span>
                  )}
                </div>
              </div>
            )) : (
              <div className="p-12 text-center">
                <div className="w-12 h-12 bg-gray-50 rounded-full flex items-center justify-center text-slate-300 mx-auto mb-3">
                  <Filter size={24} />
                </div>
                <p className="text-slate-400 text-xs">暂无匹配的单据记录</p>
              </div>
            )}
          </div>
        </div>
      )}

      {/* 新增项 Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-sm rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[80vh]">
            <div className="p-4 border-b border-gray-100 flex items-center justify-between">
              <h4 className="font-bold text-slate-800">添加{view === 'audit' ? '盘点' : '消耗'}食材</h4>
              <button onClick={() => setShowAddModal(false)} className="p-1.5 bg-gray-50 rounded-full text-slate-400">
                <X size={18} />
              </button>
            </div>
            <div className="flex-1 overflow-y-auto p-2 space-y-1">
              {inventory
                .filter(item => !currentVisibleIds.includes(item.id))
                .map(item => (
                  <button 
                    key={item.id}
                    onClick={() => addItemToView(item.id)}
                    className="w-full p-3 flex items-center justify-between hover:bg-gray-50 rounded-2xl transition-colors text-left"
                  >
                    <div>
                      <p className="text-sm font-bold text-slate-700">{item.name}</p>
                      <p className="text-[10px] text-slate-400">{item.category} · 当前库存:{item.currentStock}{item.unit}</p>
                    </div>
                    <div className={`p-1.5 rounded-lg ${view === 'audit' ? 'bg-emerald-50 text-emerald-600' : 'bg-orange-50 text-orange-600'}`}>
                      <Plus size={16} />
                    </div>
                  </button>
                ))}
              {inventory.filter(item => !currentVisibleIds.includes(item.id)).length === 0 && (
                <div className="p-8 text-center text-slate-400 text-xs">
                  所有库存食材已在列表中
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { Search, Plus, Minus, SlidersHorizontal, History, Package, ChevronRight, Calendar, X, FileText, Tag, Hash, DollarSign } from 'lucide-react';
import { InventoryItem, Category, DeliveryNote } from '../types';
import { CATEGORIES } from '../constants';

interface InventoryListProps {
  inventory: InventoryItem[];
  deliveryNotes: DeliveryNote[];
  onUpdateStock: (id: string, amount: number) => void;
}

export default function InventoryList({ inventory, onUpdateStock, deliveryNotes }: InventoryListProps) {
  const [activeSubTab, setActiveSubTab] = useState<'stock' | 'history'>('stock');
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('全部');

  // 历史单据查询状态
  const [historySearchVendor, setHistorySearchVendor] = useState('');
  const [historySearchDate, setHistorySearchDate] = useState('');
  const [selectedNote, setSelectedNote] = useState<DeliveryNote | null>(null);

  const filteredItems = inventory.filter(item => {
    const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = filterCategory === '全部' || item.category === filterCategory;
    return matchesSearch && matchesCategory;
  });

  const filteredHistory = deliveryNotes.filter(note => {
    const matchesVendor = note.vendorName.toLowerCase().includes(historySearchVendor.toLowerCase());
    const matchesDate = historySearchDate === '' || note.date.startsWith(historySearchDate);
    return matchesVendor && matchesDate;
  });

  return (
    <div className="space-y-4 animate-in fade-in duration-500 pb-10">
      {/* Sub Tabs */}
      <div className="flex bg-white p-1 rounded-2xl border border-gray-100 shadow-sm mb-2">
        <button 
          onClick={() => setActiveSubTab('stock')}
          className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-1.5 ${activeSubTab === 'stock' ? 'bg-emerald-600 text-white' : 'text-slate-500'}`}
        >
          <Package size={14} /> 实时库存
        </button>
        <button 
          onClick={() => setActiveSubTab('history')}
          className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-1.5 ${activeSubTab === 'history' ? 'bg-emerald-600 text-white' : 'text-slate-500'}`}
        >
          <History size={14} /> 单据查询
        </button>
      </div>

      {activeSubTab === 'stock' ? (
        <>
          <div className="flex items-center gap-2">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
              <input 
                type="text" 
                placeholder="搜索食材..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-9 pr-4 py-2.5 bg-white border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-emerald-500 shadow-sm outline-none"
              />
            </div>
            <button className="p-2.5 bg-white border border-gray-200 rounded-xl text-slate-600 shadow-sm active:bg-gray-50">
              <SlidersHorizontal size={20} />
            </button>
          </div>

          <div className="flex overflow-x-auto gap-2 py-1 no-scrollbar">
            <button 
              onClick={() => setFilterCategory('全部')}
              className={`whitespace-nowrap px-4 py-1.5 rounded-full text-xs font-bold transition-all ${
                filterCategory === '全部' ? 'bg-emerald-600 text-white' : 'bg-white text-slate-500 border border-gray-100'
              }`}
            >
              全部
            </button>
            {CATEGORIES.map(c => (
              <button 
                key={c}
                onClick={() => setFilterCategory(c)}
                className={`whitespace-nowrap px-4 py-1.5 rounded-full text-xs font-bold transition-all ${
                  filterCategory === c ? 'bg-emerald-600 text-white' : 'bg-white text-slate-500 border border-gray-100'
                }`}
              >
                {c}
              </button>
            ))}
          </div>

          <div className="grid grid-cols-1 gap-3">
            {filteredItems.map((item) => {
              const isLow = item.currentStock < item.minStock;
              return (
                <div key={item.id} className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm active:scale-[0.98] transition-transform">
                  <div className="flex justify-between items-start mb-3">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-emerald-50 text-emerald-600 rounded-xl flex items-center justify-center font-bold">
                        {item.name.charAt(0)}
                      </div>
                      <div>
                        <h4 className="font-bold text-slate-800 text-sm">{item.name}</h4>
                        <p className="text-[10px] text-slate-400">{item.category} · 警戒:{item.minStock}{item.unit}</p>
                      </div>
                    </div>
                    {isLow && (
                      <span className="px-2 py-0.5 bg-red-50 text-red-600 text-[10px] font-bold rounded">缺货</span>
                    )}
                  </div>

                  <div className="flex items-center justify-between">
                    <div className="flex items-baseline gap-1">
                      <span className={`text-xl font-black ${isLow ? 'text-red-500' : 'text-emerald-600'}`}>
                        {item.currentStock}
                      </span>
                      <span className="text-xs text-slate-400">{item.unit}</span>
                    </div>

                    <div className="flex items-center gap-2">
                      <button 
                        onClick={() => onUpdateStock(item.id, -1)}
                        className="w-9 h-9 flex items-center justify-center bg-gray-50 rounded-xl text-slate-600 active:bg-gray-200 transition-colors"
                      >
                        <Minus size={16} />
                      </button>
                      <button 
                        onClick={() => onUpdateStock(item.id, 1)}
                        className="w-9 h-9 flex items-center justify-center bg-emerald-50 rounded-xl text-emerald-600 active:bg-emerald-100 transition-colors"
                      >
                        <Plus size={16} />
                      </button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </>
      ) : (
        <div className="space-y-4">
          {/* 历史单据查询筛选器 */}
          <div className="grid grid-cols-2 gap-2">
            <div className="relative">
              <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
              <input 
                type="text" 
                placeholder="供应商" 
                value={historySearchVendor}
                onChange={(e) => setHistorySearchVendor(e.target.value)}
                className="w-full pl-8 pr-3 py-2 bg-white border border-gray-200 rounded-xl text-xs focus:ring-2 focus:ring-emerald-500 outline-none"
              />
            </div>
            <div className="relative">
              <Calendar className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
              <input 
                type="date" 
                value={historySearchDate}
                onChange={(e) => setHistorySearchDate(e.target.value)}
                className="w-full pl-8 pr-3 py-2 bg-white border border-gray-200 rounded-xl text-xs focus:ring-2 focus:ring-emerald-500 outline-none"
              />
            </div>
          </div>

          <div className="space-y-3">
            {filteredHistory.length > 0 ? filteredHistory.map(note => {
              const dateObj = new Date(note.date);
              const formattedName = `${note.vendorName}${dateObj.getMonth() + 1}月${dateObj.getDate()}日`;

              return (
                <div 
                  key={note.id} 
                  onClick={() => setSelectedNote(note)}
                  className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm active:bg-gray-50 transition-colors cursor-pointer"
                >
                  <div className="flex justify-between items-start">
                    <div>
                      <h5 className="text-sm font-bold text-slate-800">{formattedName}</h5>
                      <p className="text-[10px] text-slate-400 mt-1">记录时间: {dateObj.toLocaleString()}</p>
                      <div className="flex flex-wrap gap-1.5 mt-2">
                        {note.items.slice(0, 3).map((it, idx) => (
                          <span key={idx} className="px-2 py-0.5 bg-gray-50 border border-gray-100 rounded text-[9px] text-slate-500">
                            {it.name} x{it.quantity}
                          </span>
                        ))}
                        {note.items.length > 3 && <span className="text-[9px] text-slate-300 self-center">...等{note.items.length}项</span>}
                      </div>
                    </div>
                    <ChevronRight size={16} className="text-slate-300" />
                  </div>
                </div>
              );
            }) : (
              <div className="p-12 text-center">
                <div className="w-12 h-12 bg-gray-50 rounded-full flex items-center justify-center text-slate-300 mx-auto mb-3">
                  <History size={24} />
                </div>
                <p className="text-slate-400 text-xs">暂无匹配的入库单据</p>
              </div>
            )}
          </div>
        </div>
      )}

      {activeSubTab === 'stock' && filteredItems.length === 0 && (
        <div className="p-12 text-center">
          <p className="text-slate-400 text-sm">没有找到相关食材</p>
        </div>
      )}

      {/* 单据详情 Modal */}
      {selectedNote && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-sm rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[85vh] animate-in zoom-in-95 duration-200">
            {/* Header */}
            <div className="p-5 border-b border-gray-50 flex items-center justify-between bg-emerald-600 text-white">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-white/20 rounded-xl">
                  <FileText size={20} />
                </div>
                <div>
                  <h4 className="font-bold text-sm">入库单据详情</h4>
                  <p className="text-[10px] text-emerald-100 opacity-80">{selectedNote.id}</p>
                </div>
              </div>
              <button 
                onClick={() => setSelectedNote(null)} 
                className="p-1.5 hover:bg-white/10 rounded-full transition-colors"
              >
                <X size={20} />
              </button>
            </div>

            {/* Info Cards */}
            <div className="p-4 space-y-4 overflow-y-auto">
              <div className="grid grid-cols-2 gap-3">
                <div className="bg-gray-50 p-3 rounded-2xl border border-gray-100">
                  <p className="text-[9px] font-bold text-slate-400 uppercase tracking-wider mb-1">供应商</p>
                  <p className="text-xs font-bold text-slate-800">{selectedNote.vendorName}</p>
                </div>
                <div className="bg-gray-50 p-3 rounded-2xl border border-gray-100">
                  <p className="text-[9px] font-bold text-slate-400 uppercase tracking-wider mb-1">入库日期</p>
                  <p className="text-xs font-bold text-slate-800">
                    {new Date(selectedNote.date).toLocaleDateString()}
                  </p>
                </div>
              </div>

              {/* Items List */}
              <div className="space-y-2">
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">食材清单 ({selectedNote.items.length})</p>
                <div className="space-y-2">
                  {selectedNote.items.map((item, idx) => (
                    <div key={idx} className="bg-white p-3 rounded-2xl border border-gray-100 flex items-center justify-between group hover:border-emerald-200 transition-colors">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 bg-emerald-50 text-emerald-600 rounded-lg flex items-center justify-center font-bold text-xs">
                          {idx + 1}
                        </div>
                        <div>
                          <p className="text-sm font-bold text-slate-800">{item.name}</p>
                          <div className="flex items-center gap-2 mt-0.5">
                            <span className="flex items-center gap-1 text-[9px] text-slate-400">
                              <Tag size={10} /> {item.category}
                            </span>
                            {item.price > 0 && (
                              <span className="flex items-center gap-1 text-[9px] text-slate-400">
                                <DollarSign size={10} /> {item.price}/元
                              </span>
                            )}
                          </div>
                        </div>
                      </div>
                      <div className="text-right">
                        <div className="flex items-center gap-1 justify-end">
                          <span className="text-sm font-black text-emerald-600">{item.quantity}</span>
                          <span className="text-[10px] text-slate-400">{item.unit}</span>
                        </div>
                        <p className="text-[9px] text-slate-300">数量</p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Footer Action */}
            <div className="p-4 bg-gray-50 border-t border-gray-100">
              <button 
                onClick={() => setSelectedNote(null)}
                className="w-full py-3 bg-white border border-gray-200 text-slate-600 rounded-xl font-bold text-sm shadow-sm active:scale-95 transition-all"
              >
                关闭窗口
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { ClipboardList, Utensils, Search, CheckCircle, History, ChevronRight, Calendar, Filter, Trash2, Plus, X, FileText, ArrowRight, Hash } from 'lucide-react';
import { InventoryItem, AuditRecord, AuditType } from '../types';

interface AuditManagerProps {
  inventory: InventoryItem[];
  auditRecords: AuditRecord[];
  onSave: (record: AuditRecord) => void;
}

const CONSUMPTION_TYPES = ['老板带走', '员工餐', '试菜', '临时菜'];

export default function AuditManager({ inventory, auditRecords, onSave }: AuditManagerProps) {
  const [view, setView] = useState<'audit' | 'consumption' | 'query'>('audit');
  const [editStates, setEditStates] = useState<Record<string, number>>({});
  const [selectedConsumptionType, setSelectedConsumptionType] = useState('员工餐');

  // 列表管理
  const [visibleAuditIds, setVisibleAuditIds] = useState<string[]>([]);
  const [visibleConsumptionIds, setVisibleConsumptionIds] = useState<string[]>([]);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [showAddModal, setShowAddModal] = useState(false);
  const [selectedDetailRecord, setSelectedDetailRecord] = useState<AuditRecord | null>(null);

  // 初始化列表（默认显示全部）
  useEffect(() => {
    const allIds = inventory.map(i => i.id);
    setVisibleAuditIds(allIds);
    setVisibleConsumptionIds(allIds);
  }, [inventory]);

  // 当切换视图时，清空选择状态
  useEffect(() => {
    setSelectedIds(new Set());
  }, [view]);

  // 筛选状态
  const [searchDate, setSearchDate] = useState('');
  const [filterType, setFilterType] = useState<'ALL' | 'DAILY_AUDIT' | 'CONSUMPTION'>('ALL');

  const handleInputChange = (id: string, value: string) => {
    const num = parseFloat(value);
    setEditStates(prev => ({ ...prev, [id]: isNaN(num) ? 0 : num }));
  };

  const toggleSelect = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  const currentVisibleIds = view === 'audit' ? visibleAuditIds : visibleConsumptionIds;

  const toggleSelectAll = () => {
    if (selectedIds.size === currentVisibleIds.length) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(currentVisibleIds));
    }
  };

  const batchDelete = () => {
    if (selectedIds.size === 0) return;
    if (view === 'audit') {
      setVisibleAuditIds(prev => prev.filter(id => !selectedIds.has(id)));
    } else {
      setVisibleConsumptionIds(prev => prev.filter(id => !selectedIds.has(id)));
    }
    setSelectedIds(new Set());
  };

  const addItemToView = (id: string) => {
    if (view === 'audit') {
      if (!visibleAuditIds.includes(id)) setVisibleAuditIds(prev => [...prev, id]);
    } else {
      if (!visibleConsumptionIds.includes(id)) setVisibleConsumptionIds(prev => [...prev, id]);
    }
    setShowAddModal(false);
  };

  const submit = (type: AuditType) => {
    const activeIds = type === 'DAILY_AUDIT' ? visibleAuditIds : visibleConsumptionIds;
    const itemsToProcess = inventory.filter(i => activeIds.includes(i.id));

    const items = itemsToProcess
      .filter(item => editStates[item.id] !== undefined && editStates[item.id] !== 0)
      .map(item => ({
        itemId: item.id,
        itemName: item.name,
        previousStock: item.currentStock,
        newStock: type === 'DAILY_AUDIT' 
          ? editStates[item.id] 
          : Math.max(0, item.currentStock - editStates[item.id]),
        diff: type === 'DAILY_AUDIT' 
          ? editStates[item.id] - item.currentStock 
          : -editStates[item.id]
      }));

    if (items.length === 0) {
      alert("请至少输入一项有效数据");
      return;
    }

    const record: AuditRecord = {
      id: `audit-${Date.now()}`,
      date: new Date().toISOString(),
      type,
      consumptionType: type === 'CONSUMPTION' ? selectedConsumptionType : undefined,
      items
    };

    onSave(record);
    setEditStates({});
    setSelectedIds(new Set());
  };

  const filteredAuditRecords = auditRecords.filter(record => {
    const dateMatch = searchDate === '' || record.date.startsWith(searchDate);
    const typeMatch = filterType === 'ALL' || record.type === filterType;
    return dateMatch && typeMatch;
  });

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-10">
      {/* Sub Tabs */}
      <div className="flex bg-white p-1 rounded-2xl border border-gray-100 shadow-sm">
        <button 
          onClick={() => setView('audit')}
          className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-1.5 ${view === 'audit' ? 'bg-emerald-600 text-white' : 'text-slate-500'}`}
        >
          <ClipboardList size={14} /> 每日盘点
        </button>
        <button 
          onClick={() => setView('consumption')}
          className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-1.5 ${view === 'consumption' ? 'bg-emerald-600 text-white' : 'text-slate-500'}`}
        >
          <Utensils size={14} /> 消耗填写
        </button>
        <button 
          onClick={() => setView('query')}
          className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-1.5 ${view === 'query' ? 'bg-emerald-600 text-white' : 'text-slate-500'}`}
        >
          <Search size={14} /> 单据查询
        </button>
      </div>

      {view !== 'query' && (
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <div className={`${view === 'audit' ? 'bg-emerald-50 border-emerald-100' : 'bg-orange-50 border-orange-100'} px-4 py-3 rounded-2xl border flex-1 mr-3`}>
              <h4 className={`font-bold text-sm ${view === 'audit' ? 'text-emerald-800' : 'text-orange-800'}`}>
                {view === 'audit' ? '当前待盘点项' : '当前消耗录入项'}
              </h4>
              <p className={`text-[10px] mt-1 ${view === 'audit' ? 'text-emerald-600' : 'text-orange-600'}`}>
                {view === 'audit' ? '勾选并录入实存，未填写的项将不会被更新。' : '勾选并录入消耗量。'}
              </p>
            </div>
            {selectedIds.size > 0 && (
              <button 
                onClick={batchDelete}
                className="p-3 bg-red-50 text-red-600 rounded-2xl border border-red-100 shadow-sm active:scale-95 transition-all flex items-center gap-2"
              >
                <Trash2 size={18} />
                <span className="text-xs font-bold">{selectedIds.size}</span>
              </button>
            )}
          </div>

          {view === 'consumption' && (
            <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3 block">消耗类型</label>
              <div className="flex flex-wrap gap-2">
                {CONSUMPTION_TYPES.map(type => (
                  <button
                    key={type}
                    onClick={() => setSelectedConsumptionType(type)}
                    className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all border ${
                      selectedConsumptionType === type 
                        ? 'bg-orange-600 text-white border-orange-600 shadow-sm' 
                        : 'bg-white text-slate-500 border-gray-100'
                    }`}
                  >
                    {type}
                  </button>
                ))}
              </div>
            </div>
          )}

          <div className="flex items-center gap-2 px-1 mb-1">
             <button 
                onClick={toggleSelectAll}
                className={`text-[10px] font-bold transition-colors ${selectedIds.size === currentVisibleIds.length ? 'text-emerald-600' : 'text-slate-400'}`}
             >
               {selectedIds.size === currentVisibleIds.length ? '取消全选' : '全选项'}
             </button>
          </div>

          <div className="space-y-3">
            {inventory.filter(i => currentVisibleIds.includes(i.id)).map(item => (
              <div key={item.id} className={`bg-white p-4 rounded-2xl border transition-all flex items-center gap-3 ${selectedIds.has(item.id) ? (view === 'audit' ? 'border-emerald-500 bg-emerald-50/30' : 'border-orange-500 bg-orange-50/30') : 'border-gray-100'}`}>
                <input 
                  type="checkbox" 
                  checked={selectedIds.has(item.id)}
                  onChange={() => toggleSelect(item.id)}
                  className={`w-5 h-5 rounded-lg border-gray-300 focus:ring-offset-0 ${view === 'audit' ? 'text-emerald-600 focus:ring-emerald-500' : 'text-orange-600 focus:ring-orange-500'}`}
                />
                <div className="flex-1">
                  <p className="font-bold text-slate-800 text-sm">{item.name}</p>
                  <p className="text-[10px] text-slate-400">
                    {view === 'audit' ? `账面：${item.currentStock}${item.unit}` : `可用：${item.currentStock}${item.unit}`}
                  </p>
                </div>
                <div className="flex items-center gap-2">
                  <input 
                    type="number" 
                    placeholder={view === 'audit' ? "实存" : "消耗"}
                    value={editStates[item.id] ?? ''}
                    onChange={(e) => handleInputChange(item.id, e.target.value)}
                    className={`w-20 text-right px-2 py-1.5 bg-gray-50 border-none rounded-lg text-sm font-bold focus:ring-2 ${view === 'audit' ? 'text-emerald-600 focus:ring-emerald-500' : 'text-orange-600 focus:ring-orange-500'}`}
                  />
                  <span className="text-xs text-slate-400 font-medium">{item.unit}</span>
                </div>
              </div>
            ))}

            {/* 新增行按钮 */}
            <button 
              onClick={() => setShowAddModal(true)}
              className="w-full py-4 border-2 border-dashed border-gray-200 rounded-2xl text-slate-400 flex items-center justify-center gap-2 hover:border-emerald-300 hover:text-emerald-500 transition-all active:scale-[0.98]"
            >
              <Plus size={20} />
              <span className="text-sm font-bold">增加一行/新增食材</span>
            </button>
          </div>

          <button 
            onClick={() => submit(view === 'audit' ? 'DAILY_AUDIT' : 'CONSUMPTION')}
            className={`w-full py-4 text-white rounded-2xl font-bold shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2 ${view === 'audit' ? 'bg-emerald-600 shadow-emerald-200' : 'bg-orange-600 shadow-orange-200'}`}
          >
            <CheckCircle size={20} />
            {view === 'audit' ? '提交盘点结果' : '提交消耗记录'}
          </button>
        </div>
      )}

      {view === 'query' && (
        <div className="space-y-4">
          <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm space-y-4">
            <div className="relative">
              <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
              <input 
                type="date" 
                value={searchDate}
                onChange={(e) => setSearchDate(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
              />
            </div>

            <div className="flex gap-2">
              <button
                onClick={() => setFilterType('ALL')}
                className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all border ${
                  filterType === 'ALL' ? 'bg-slate-800 text-white border-slate-800' : 'bg-white text-slate-500 border-gray-100'
                }`}
              >
                全部单据
              </button>
              <button
                onClick={() => setFilterType('DAILY_AUDIT')}
                className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all border ${
                  filterType === 'DAILY_AUDIT' ? 'bg-emerald-600 text-white border-emerald-600' : 'bg-white text-slate-500 border-gray-100'
                }`}
              >
                盘点单据
              </button>
              <button
                onClick={() => setFilterType('CONSUMPTION')}
                className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all border ${
                  filterType === 'CONSUMPTION' ? 'bg-orange-600 text-white border-orange-600' : 'bg-white text-slate-500 border-gray-100'
                }`}
              >
                消耗单据
              </button>
            </div>
          </div>

          <div className="space-y-3">
            {filteredAuditRecords.length > 0 ? filteredAuditRecords.map(record => (
              <div 
                key={record.id} 
                onClick={() => setSelectedDetailRecord(record)}
                className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm active:bg-gray-50 transition-colors cursor-pointer"
              >
                <div className="flex justify-between items-start mb-2">
                  <div className="flex items-center gap-2">
                    <div className={`p-1.5 rounded-lg ${record.type === 'DAILY_AUDIT' ? 'bg-emerald-50 text-emerald-600' : 'bg-orange-50 text-orange-600'}`}>
                      {record.type === 'DAILY_AUDIT' ? <ClipboardList size={16} /> : <Utensils size={16} />}
                    </div>
                    <div>
                      <h5 className="text-sm font-bold text-slate-800 flex items-center gap-2">
                        {record.type === 'DAILY_AUDIT' ? '盘点单据' : '消耗单据'}
                        {record.consumptionType && (
                          <span className="px-1.5 py-0.5 bg-orange-50 text-orange-600 text-[9px] border border-orange-100 rounded">
                            {record.consumptionType}
                          </span>
                        )}
                      </h5>
                      <p className="text-[10px] text-slate-400">{new Date(record.date).toLocaleString()}</p>
                    </div>
                  </div>
                  <ChevronRight size={16} className="text-slate-300" />
                </div>
                <div className="flex flex-wrap gap-1.5 mt-3">
                  {record.items.slice(0, 3).map((it, idx) => (
                    <span key={idx} className="px-2 py-0.5 bg-gray-50 border border-gray-100 rounded text-[9px] text-slate-500 font-medium">
                      {it.itemName}: {it.diff > 0 ? '+' : ''}{it.diff}
                    </span>
                  ))}
                  {record.items.length > 3 && (
                    <span className="text-[9px] text-slate-300 self-center">等{record.items.length}项...</span>
                  )}
                </div>
              </div>
            )) : (
              <div className="p-12 text-center">
                <div className="w-12 h-12 bg-gray-50 rounded-full flex items-center justify-center text-slate-300 mx-auto mb-3">
                  <Filter size={24} />
                </div>
                <p className="text-slate-400 text-xs">暂无匹配的单据记录</p>
              </div>
            )}
          </div>
        </div>
      )}

      {/* 新增项 Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-sm rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[80vh]">
            <div className="p-4 border-b border-gray-100 flex items-center justify-between">
              <h4 className="font-bold text-slate-800">添加{view === 'audit' ? '盘点' : '消耗'}食材</h4>
              <button onClick={() => setShowAddModal(false)} className="p-1.5 bg-gray-50 rounded-full text-slate-400">
                <X size={18} />
              </button>
            </div>
            <div className="flex-1 overflow-y-auto p-2 space-y-1">
              {inventory
                .filter(item => !currentVisibleIds.includes(item.id))
                .map(item => (
                  <button 
                    key={item.id}
                    onClick={() => addItemToView(item.id)}
                    className="w-full p-3 flex items-center justify-between hover:bg-gray-50 rounded-2xl transition-colors text-left"
                  >
                    <div>
                      <p className="text-sm font-bold text-slate-700">{item.name}</p>
                      <p className="text-[10px] text-slate-400">{item.category} · 当前库存:{item.currentStock}{item.unit}</p>
