import React, { useState, useRef } from 'react';
import { Camera, FileUp, Plus, Trash2, CheckCircle, Loader2, X, Square, CheckSquare } from 'lucide-react';
import { scanDeliveryNote } from '../services/gemini';
import { Vendor, InventoryItem, DeliveryNote, DeliveryItem, Category } from '../types';
import { CATEGORIES, UNITS } from '../constants';

interface InventoryEntryProps {
  vendors: Vendor[];
  inventory: InventoryItem[];
  onComplete: (note: DeliveryNote) => void;
}

export default function InventoryEntry({ vendors, inventory, onComplete }: InventoryEntryProps) {
  const [entryMode, setEntryMode] = useState<'ai' | 'review'>('ai');
  const [isLoading, setIsLoading] = useState(false);
  const [vendorId, setVendorId] = useState('');
  const [items, setItems] = useState<DeliveryItem[]>([]);
  const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set());
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsLoading(true);
    try {
      const reader = new FileReader();
      reader.onload = async () => {
        const base64 = (reader.result as string).split(',')[1];
        const result = await scanDeliveryNote(base64);
        const foundVendor = vendors.find(v => v.name.includes(result.vendorName) || result.vendorName.includes(v.name));
        if (foundVendor) setVendorId(foundVendor.id);
        setItems(result.items.map((it: any) => ({
          name: it.name,
          quantity: it.quantity,
          unit: it.unit,
          category: it.category as Category,
          price: it.price || 0
        })));
        setEntryMode('review');
      };
      reader.readAsDataURL(file);
    } catch (error) {
      alert("识别失败，请重试");
    } finally {
      setIsLoading(false);
    }
  };

  const updateItem = (idx: number, updates: Partial<DeliveryItem>) => {
    const newItems = [...items];
    newItems[idx] = { ...newItems[idx], ...updates };
    setItems(newItems);
  };

  const removeItem = (idx: number) => {
    setItems(items.filter((_, i) => i !== idx));
    const newSelected = new Set(selectedIndices);
    newSelected.delete(idx);
    setSelectedIndices(newSelected);
  };

  const toggleSelect = (idx: number) => {
    const newSelected = new Set(selectedIndices);
    if (newSelected.has(idx)) {
      newSelected.delete(idx);
    } else {
      newSelected.add(idx);
    }
    setSelectedIndices(newSelected);
  };

  const toggleSelectAll = () => {
    if (selectedIndices.size === items.length && items.length > 0) {
      setSelectedIndices(new Set());
    } else {
      setSelectedIndices(new Set(items.map((_, i) => i)));
    }
  };

  const batchDelete = () => {
    if (selectedIndices.size === 0) return;
    setItems(items.filter((_, i) => !selectedIndices.has(i)));
    setSelectedIndices(new Set());
  };

  const handleSave = () => {
    if (!vendorId) {
      alert("请选择供应商");
      return;
    }
    if (items.length === 0) {
      alert("请至少添加一项食材");
      return;
    }
    const vendor = vendors.find(v => v.id === vendorId);
    onComplete({
      id: `dn-${Date.now()}`,
      vendorId,
      vendorName: vendor?.name || '未知',
      date: new Date().toISOString(),
      items,
      status: 'completed'
    });
  };

  if (entryMode === 'ai') {
    return (
      <div className="flex flex-col items-center justify-center min-h-[70vh] space-y-8 animate-in zoom-in-95 duration-300">
        <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 shadow-inner">
          <Camera size={48} />
        </div>
        <div className="text-center px-6">
          <h3 className="text-xl font-black text-slate-800">拍照智能识单</h3>
          <p className="text-slate-500 text-sm mt-2 leading-relaxed">
            对准送货单拍照，AI 将自动提取供应商信息及菜品详情，无需手动录入。
          </p>
        </div>
        <div className="w-full space-y-3 px-4">
          <button 
            onClick={() => fileInputRef.current?.click()}
            disabled={isLoading}
            className="w-full py-4 bg-emerald-600 text-white rounded-2xl font-bold text-lg shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2"
          >
            {isLoading ? <Loader2 className="animate-spin" /> : <Camera size={24} />}
            {isLoading ? '正在智能识别...' : '立即拍照 / 上传'}
          </button>
          <button 
            onClick={() => {
              setItems([{ name: '', quantity: 1, unit: 'kg', category: Category.OTHER, price: 0 }]);
              setEntryMode('review');
            }}
            className="w-full py-4 bg-white text-slate-600 rounded-2xl font-bold border border-gray-200 active:bg-gray-50"
          >
            手动录入
          </button>
        </div>
        <input type="file" className="hidden" ref={fileInputRef} accept="image/*" onChange={handleFileUpload} />
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-20 animate-in slide-in-from-right-4 duration-300">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-bold text-slate-800">确认单据信息</h3>
        <button onClick={() => { setEntryMode('ai'); setSelectedIndices(new Set()); }} className="text-emerald-600 text-xs font-bold">重新扫描</button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm space-y-4">
        <div>
          <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">送货供应商</label>
          <select 
            value={vendorId}
            onChange={(e) => setVendorId(e.target.value)}
            className="w-full mt-1 p-2 bg-gray-50 border-none rounded-lg text-sm font-bold text-slate-700 outline-none"
          >
            <option value="">点击选择供应商</option>
            {vendors.map(v => <option key={v.id} value={v.id}>{v.name}</option>)}
          </select>
        </div>
      </div>

      <div className="space-y-3">
        <div className="flex items-center justify-between px-1">
          <div className="flex items-center gap-3">
            <button 
              onClick={toggleSelectAll}
              className="flex items-center gap-1.5 text-[10px] font-bold text-slate-400 uppercase tracking-widest"
            >
              {selectedIndices.size === items.length && items.length > 0 ? <CheckSquare size={14} className="text-emerald-600" /> : <Square size={14} />}
              全选
            </button>
            <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">清单内容 ({items.length})</label>
          </div>
          <div className="flex items-center gap-2">
            {selectedIndices.size > 0 && (
              <button 
                onClick={batchDelete}
                className="p-1.5 bg-red-50 text-red-600 rounded-lg hover:bg-red-100 transition-colors flex items-center gap-1"
                title="删除选中"
              >
                <Trash2 size={16} />
                <span className="text-[10px] font-bold">{selectedIndices.size}</span>
              </button>
            )}
            <button 
              onClick={() => setItems([...items, { name: '', quantity: 1, unit: 'kg', category: Category.OTHER, price: 0 }])} 
              className="p-1.5 bg-emerald-50 text-emerald-600 rounded-lg hover:bg-emerald-100 transition-colors"
              title="添加一行"
            >
              <Plus size={18} />
            </button>
          </div>
        </div>

        {items.length > 0 ? items.map((item, idx) => (
          <div key={idx} className={`bg-white p-3 rounded-2xl border transition-all flex gap-3 relative overflow-hidden ${selectedIndices.has(idx) ? 'border-emerald-500 bg-emerald-50/20' : 'border-gray-100 shadow-sm'}`}>
            <div className="flex items-center">
              <button 
                onClick={() => toggleSelect(idx)}
                className={`transition-colors ${selectedIndices.has(idx) ? 'text-emerald-600' : 'text-slate-300'}`}
              >
                {selectedIndices.has(idx) ? <CheckSquare size={20} /> : <Square size={20} />}
              </button>
            </div>

            <div className="flex-1 space-y-3">
              <div className="flex justify-between items-center">
                <input 
                  type="text" 
                  value={item.name} 
                  placeholder="商品名称"
                  onChange={(e) => updateItem(idx, { name: e.target.value })}
                  className="w-full font-bold text-slate-800 border-none p-0 focus:ring-0 text-sm bg-transparent"
                />
                <button onClick={() => removeItem(idx)} className="text-slate-300 hover:text-red-500 transition-colors ml-2">
                  <X size={16} />
                </button>
              </div>

              <div className="flex items-center gap-2">
                <div className="flex-1 bg-gray-50/50 p-2 rounded-lg">
                  <p className="text-[8px] text-slate-400 uppercase font-bold">数量</p>
                  <input 
                    type="number" 
                    value={item.quantity} 
                    onChange={(e) => updateItem(idx, { quantity: parseFloat(e.target.value) || 0 })}
                    className="w-full bg-transparent border-none p-0 text-xs font-bold text-slate-700 focus:ring-0"
                  />
                </div>
                <div className="flex-1 bg-gray-50/50 p-2 rounded-lg">
                  <p className="text-[8px] text-slate-400 uppercase font-bold">单位</p>
                  <select 
                    value={item.unit}
                    onChange={(e) => updateItem(idx, { unit: e.target.value })}
                    className="w-full bg-transparent border-none p-0 text-xs font-bold text-slate-700 focus:ring-0"
                  >
                    {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                  </select>
                </div>
                <div className="flex-[1.5] bg-gray-50/50 p-2 rounded-lg">
                  <p className="text-[8px] text-slate-400 uppercase font-bold">品类</p>
                  <select 
                    value={item.category}
                    onChange={(e) => updateItem(idx, { category: e.target.value as Category })}
                    className="w-full bg-transparent border-none p-0 text-xs font-bold text-slate-700 focus:ring-0"
                  >
                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
              </div>
            </div>
          </div>
        )) : (
          <div className="p-12 text-center border-2 border-dashed border-gray-100 rounded-3xl">
            <p className="text-slate-300 text-xs font-bold">清单为空，请点击右上角“+”添加食材</p>
          </div>
        )}
      </div>

      <div className="fixed bottom-24 left-4 right-4 max-w-md mx-auto">
        <button 
          onClick={handleSave}
          className="w-full py-4 bg-emerald-600 text-white rounded-2xl font-bold shadow-xl flex items-center justify-center gap-2 active:scale-95 transition-all disabled:opacity-50 disabled:active:scale-100"
          disabled={items.length === 0}
        >
          <CheckCircle size={20} />
          完成入库
        </button>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import InventoryList from './components/InventoryList';
import InventoryEntry from './components/InventoryEntry';
import AuditManager from './components/AuditManager';
import { InventoryItem, Vendor, DeliveryNote, Category, AuditRecord } from './types';
import { NAV_ITEMS } from './constants';

const INITIAL_VENDORS: Vendor[] = [
  { id: 'v1', name: '兴隆蔬菜批发', contact: '张老板', phone: '13800138000', address: '新发地市场A区', categories: [Category.VEGETABLE, Category.FRUIT], paymentMethod: '周结' },
  { id: 'v2', name: '诚顺肉品供应', contact: '王经理', phone: '13900139000', address: '新发地市场B区', categories: [Category.MEAT], paymentMethod: '日结' },
];

const INITIAL_INVENTORY: InventoryItem[] = [
  { id: 'i1', name: '大白菜', category: Category.VEGETABLE, unit: 'kg', price: 2.5, currentStock: 45, minStock: 50, lastRestockDate: '2023-11-20' },
  { id: 'i2', name: '猪里脊', category: Category.MEAT, unit: 'kg', price: 32, currentStock: 12, minStock: 10, lastRestockDate: '2023-11-22' },
  { id: 'i3', name: '青岛啤酒', category: Category.BEVERAGE, unit: '箱', price: 48, currentStock: 5, minStock: 10, lastRestockDate: '2023-10-15' },
];

export default function App() {
  const [activeTab, setActiveTab] = useState('inventory');
  const [vendors] = useState<Vendor[]>(INITIAL_VENDORS);
  const [inventory, setInventory] = useState<InventoryItem[]>(INITIAL_INVENTORY);
  const [deliveryNotes, setDeliveryNotes] = useState<DeliveryNote[]>([]);
  const [auditRecords, setAuditRecords] = useState<AuditRecord[]>([]);

  const handleUpdateStock = (itemId: string, amount: number) => {
    setInventory(prev => prev.map(item => 
      item.id === itemId ? { ...item, currentStock: Math.max(0, item.currentStock + amount) } : item
    ));
  };

  const handleSaveAudit = (record: AuditRecord) => {
    setAuditRecords(prev => [record, ...prev]);
    setInventory(prev => prev.map(item => {
      const auditItem = record.items.find(ai => ai.itemId === item.id);
      if (auditItem) {
        return { ...item, currentStock: auditItem.newStock };
      }
      return item;
    }));
    setActiveTab('inventory');
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'inventory': 
        return <InventoryList inventory={inventory} onUpdateStock={handleUpdateStock} deliveryNotes={deliveryNotes} />;
      case 'audit': 
        return (
          <AuditManager 
            inventory={inventory} 
            auditRecords={auditRecords} 
            onSave={handleSaveAudit} 
          />
        );
      case 'delivery': 
        return (
          <InventoryEntry 
            vendors={vendors} 
            inventory={inventory}
            onComplete={(note) => {
              setDeliveryNotes(prev => [note, ...prev]);
              const updatedInventory = [...inventory];
              note.items.forEach(item => {
                const existing = updatedInventory.find(i => i.name === item.name);
                if (existing) {
                  existing.currentStock += item.quantity;
                  existing.lastRestockDate = note.date;
                } else {
                  updatedInventory.push({
                    id: `i-${Date.now()}-${Math.random()}`,
                    name: item.name,
                    category: item.category,
                    unit: item.unit,
                    price: item.price,
                    currentStock: item.quantity,
                    minStock: 10,
                    lastRestockDate: note.date
                  });
                }
              });
              setInventory(updatedInventory);
              setActiveTab('inventory');
            }}
          />
        );
      default: 
        return <InventoryList inventory={inventory} onUpdateStock={handleUpdateStock} deliveryNotes={deliveryNotes} />;
    }
  };

  return (
    <div className="flex flex-col h-screen bg-gray-50 max-w-md mx-auto shadow-2xl overflow-hidden border-x border-gray-200">
      <header className="sticky top-0 z-30 bg-white/80 backdrop-blur-md border-b border-gray-100 px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-emerald-600 rounded-lg flex items-center justify-center text-white font-bold text-sm">餐</div>
          <h1 className="font-bold text-lg text-slate-800 tracking-tight">餐管家</h1>
        </div>
        {/* 移除了铃铛和用户图标区域 */}
      </header>

      <main className="flex-1 overflow-y-auto pb-28 scroll-smooth">
        <div className="p-4">
          {renderContent()}
        </div>
      </main>

      {/* 优化后的底部导航栏 */}
      <footer className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white/95 backdrop-blur-lg border-t border-gray-100 px-2 py-3 flex items-end justify-around z-40 shadow-[0_-10px_30px_-15px_rgba(0,0,0,0.1)]">
        {NAV_ITEMS.map((item, index) => {
          const isActive = activeTab === item.id;

          if (item.isCenter) {
            return (
              <div key={item.id} className="relative flex-1 flex justify-center h-full">
                <button
                  onClick={() => setActiveTab(item.id)}
                  className={`absolute -top-10 flex flex-col items-center justify-center w-16 h-16 bg-emerald-600 rounded-full text-white shadow-[0_8px_20px_-5px_rgba(5,150,105,0.4)] border-4 border-white active:scale-90 active:shadow-inner transition-all duration-200 group`}
                >
                  <div className="transition-transform group-hover:scale-110">
                    {item.icon}
                  </div>
                </button>
                <span className={`text-[10px] mt-8 font-bold ${isActive ? 'text-emerald-600' : 'text-slate-400 opacity-60'}`}>
                  {item.label}
                </span>
              </div>
            );
          }

          return (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`flex-1 flex flex-col items-center justify-center gap-1 transition-all duration-200 py-1 rounded-2xl ${
                isActive ? 'text-emerald-600' : 'text-slate-400'
              }`}
            >
              <div className={`p-1.5 rounded-xl transition-all duration-300 ${isActive ? 'bg-emerald-50 scale-110' : 'bg-transparent'}`}>
                {item.icon}
              </div>
              <span className={`text-[10px] font-bold tracking-wide ${isActive ? 'opacity-100' : 'opacity-70'}`}>
                {item.label}
              </span>
              {isActive && (
                <div className="w-1 h-1 bg-emerald-600 rounded-full animate-in fade-in zoom-in duration-300"></div>
              )}
            </button>
          );
        })}
      </footer>
    </div>
  );
}

